(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,64405,2512,e=>{"use strict";var t=e.i(10595),n=e.i(55160);let o=["be-rule","present-simple","present-continuous","present-perfect","present-perfect-continuous","past-simple","past-continuous","past-perfect","past-perfect-continuous","future-simple","going-to","future-continuous","future-perfect","future-perfect-continuous","time-clauses","conditionals","used-to","sequence-of-tenses"],a=[{id:"be-rule",group:"key",name:"Am / is / are / was / were",ruName:"Когда нужен am/is/are/was/were",short:"Before another verb, be needs -ing or V3 (or to + verb). Never be + V1 or V2.",idea:"Am/is/are/was/were — это не значок времени, который ставится перед каждым глаголом. Перед другим глаголом be нужен только в двух случаях: с -ing (действие в процессе: I'm working, I was working) и с V3 (действие сделали с подлежащим: It was cancelled). Во всех остальных случаях время показывает сам глагол (I work, he works, we went), а be живёт отдельно — с прилагательным, существительным или местом: I'm tired, she was at home.",category:"be-verb",forms:[{label:"+ -ing",parts:["be","V-ing","= continuous"],example:"Look, it **is snowing**!"},{label:"+ V3",parts:["be","V3","= passive"],example:"The parcel **was delivered** yesterday."},{label:"+ adj / place",parts:["be","adjective / noun / place"],example:"We **were tired**, and Max **was at work**."},{label:"+ to + verb",parts:["be","to + V1"],example:"My plan **is to** find a new job."},{label:"✗ + V1 / V2",parts:["be","V1 / V2 / V-s","= delete be"],example:"I **agree**. We **went** home. It **depends**."}],uses:[{en:"be + -ing: in progress",ru:"Действие в процессе в какой-то момент — это continuous. Am/is/are + -ing — идёт сейчас, was/were + -ing — шло в прошлом.",example:{en:"She **was driving** when her boss called.",ru:"Она была за рулём, когда позвонил начальник."}},{en:"be + V3: done to it",ru:"Действие совершают над подлежащим (кто-то сделал это с ним) — это пассив: am/is/are + V3 в настоящем, was/were + V3 в прошлом.",example:{en:"Our flight **was cancelled** because of the snow.",ru:"Наш рейс отменили из-за снега."}},{en:"be + adjective / place",ru:"Be сам по себе значит «быть, находиться»: с прилагательным, существительным или местом. Сюда же V3 в роли прилагательного: tired, interested, bored, married.",example:{en:"Sorry, I'**m late**. The traffic **was terrible**.",ru:"Извини за опоздание, пробки были жуткие."}},{en:"be + to + verb",ru:"Конструкция be + to + глагол — правильная: так говорят о цели, задаче или плане (My job is to…, The idea was to…).",example:{en:"My plan **is to** find a remote job by summer.",ru:"Мой план — найти удалённую работу к лету."}},{en:"Was or just V2?",ru:"Was/were живут по тому же правилу: was + -ing, was + V3, was + прилагательное или место. А обычное действие в прошлом («пошли, позвонили, случилось») — это просто V2 без was: we went, she called, it happened.",example:{en:"We **were tired**, so we **went** home early.",ru:"Мы устали, поэтому рано ушли домой."}}],signals:[{word:"-ing (working, waiting)",note:"если это сказуемое, be нужен: is working, was waiting (но I like working — без be)"},{word:"V3 (made, sent, cancelled)",note:"be нужен, если действие сделали с подлежащим: was cancelled; «уже сделал» — have + V3: has sent"},{word:"tired, interested, bored, married",note:"V3 в роли прилагательного, be нужен: I'm tired"},{word:"sure, ready, late, afraid",note:"прилагательные, be нужен: I'm sure, I'm afraid (= я боюсь)"},{word:"at home, at work, in Kazan",note:"место, be нужен: She's at work"},{word:"to + verb (is to, was to)",note:"My plan is to… — правильно"},{word:"agree, depend, live, know",note:"обычные глаголы, без be: I agree, it depends; be — только с -ing: I'm living"},{word:"went, saw, came, happened",note:"V2, без was: I went, it happened"},{word:"born",note:"только с be: I was born in 1995"}],versus:[{tense:"past-simple",ru:"Was + V3 — встречу перенесли: кто-то сделал это с ней. Если подлежащее само совершает действие, хватит V2 без was: we moved.",a:{en:"The meeting **was moved** to Friday.",ru:"Встречу перенесли на пятницу."},b:{en:"We **moved** the meeting to Friday.",ru:"Мы перенесли встречу на пятницу."}},{tense:"present-simple",ru:"Is closed — состояние «закрыто» (be + V3 как прилагательное). Closes — действие по расписанию, это present simple без is.",a:{en:"The pharmacy **is closed** now.",ru:"Аптека сейчас закрыта."},b:{en:"The pharmacy **closes** at nine.",ru:"Аптека закрывается в девять."}},{tense:"present-perfect",ru:"Is open — состояние «открыто». Has opened — действие только что случилось, и здесь нужен has, а не is; так же The film has started, а не is started.",a:{en:"The new café **is open** now.",ru:"Новое кафе уже работает."},b:{en:"The new café **has** just **opened**.",ru:"Новое кафе только что открылось."}}],mistakes:[{wrong:"I am agree with this plan.",right:"I agree with this plan.",why:"Agree — это глагол «соглашаться», а не прилагательное «согласен», поэтому без am; вопрос и отрицание — через do: Do you agree? I don't agree."},{wrong:"We were went to the cinema yesterday.",right:"We went to the cinema yesterday.",why:"Went — уже прошедшее время (V2), перед ним was/were не ставится; в вопросе и отрицании — did: Did you go? We didn't go."},{wrong:"It is depends on the price.",right:"It depends on the price.",why:"Перед формой на -s be не ставится никогда: -s уже показывает настоящее время."},{wrong:"I'm teach English online.",right:"I teach English online.",why:"Сразу после am/is/are V1 не ставится: либо I teach (постоянно), либо I'm teaching (временно, с -ing)."},{wrong:"The film is started at 8.",right:"The film starts at 8.",why:"Фильм начинается сам, над ним ничего не делают, значит это не пассив: по расписанию starts, в прошлом started, «уже идёт» — has started."},{wrong:"I born in 1995.",right:"I was born in 1995.",why:"Born — это V3 («быть рождённым»), поэтому здесь как раз нужен was."}],trick:"Смотри, что стоит после am/is/are/was/were (наречия вроде not, always, really не в счёт): глагол там может быть только с -ing или в форме V3, иначе убери be и поставь сам глагол в нужное время (I agree, we went); прилагательное, существительное, место или to + глагол — пожалуйста. Если V2 и V3 совпадают (started, moved), спроси: «это кто-то сделал с подлежащим?» Да — was moved, нет — просто started.",examples:[{en:"We **agree** with the plan, but it **depends** on the budget.",ru:"Мы согласны с планом, но всё зависит от бюджета."},{en:"She **was waiting** for a taxi when it **started** to rain.",ru:"Она ждала такси, когда начался дождь."},{en:"All the tickets **were sold** in two hours.",ru:"Все билеты раскупили за два часа."},{en:"We **went** to the office yesterday, but nobody **was** there.",ru:"Вчера мы поехали в офис, но там никого не было."},{en:"**Are** you **interested** in the new position?",ru:"Тебе интересна эта вакансия?"},{en:"Our daughter **was born** in Kazan in 2018.",ru:"Наша дочь родилась в Казани в 2018 году."},{en:"The app **is updated** every two weeks.",ru:"Приложение обновляется каждые две недели."},{en:"He **lives** in Berlin, but this month he'**s working** from Lisbon.",ru:"Он живёт в Берлине, но в этом месяце работает из Лиссабона."},{en:"What **happened**? Why **is** everyone so **quiet**?",ru:"Что случилось? Почему все такие тихие?"},{en:"We'**re tired** because the baby **didn't sleep** last night.",ru:"Мы устали, потому что малыш не спал ночью."}],exercises:[{id:"br-we-went",type:"choice",prompt:"Last weekend we ___ to my parents' place in the country.",options:["were went","went","were go","have gone"],answer:1,rule:"Past simple: V2 alone, no was/were",explain:"Went is already past (V2), so it needs no helper. Was and were go before -ing or V3, never before a past form like went.",ruHint:"«Мы ездили» — просто went, без were."},{id:"br-afraid",type:"choice",prompt:"I ___ of flying, so we usually take the train.",options:["am afraid","afraid","am fear","fear"],answer:0,rule:"be + adjective: I'm afraid, I'm sure, I'm late",explain:"Afraid is an adjective, not a verb, so it needs be: I'm afraid of flying. Without am, the sentence has no verb.",ruHint:"«Я боюсь» = I'm afraid: be + прилагательное."},{id:"br-depends",type:"fill",before:"I don't always cycle to work. It ",after:" on the weather.",answers:["depends"],base:"depend",rule:"No be before an -s form: it depends",explain:"You are talking about what usually happens, so use present simple. Depend is a normal verb: with it, add -s: depends. 'It is depends' has two verbs where English needs one.",ruHint:"«Зависит» — it depends, без is."},{id:"br-i-live",type:"errorTap",sentence:"I'm live near the office, so I walk to work.",wrong:0,correct:"I live near the office, so I walk to work.",rule:"No be + bare verb: I live (or I'm living)",explain:"Live is a normal verb, so drop 'm: I live. 'I'm living' is possible too, but only for a temporary situation.",ruHint:"Be + V1 не бывает: I live."},{id:"br-was-born",type:"fill",before:"My grandmother ",after:" in Omsk in 1952.",answers:["was born"],base:"be born",rule:"be born: was + V3, so here was is needed",explain:"Born is V3: she didn't do it, it happened to her. So it works like a passive: was born.",ruHint:"«Родилась» = was born: здесь was нужен."},{id:"br-was-built",type:"choice",prompt:"This bridge ___ in 1890 and is still in use today.",options:["built","was build","was built","is built"],answer:2,rule:"Done to the subject → was/were + V3 (passive)",explain:"The bridge didn't build anything: people built it. That is passive in the past: was + V3 (built).",ruHint:"«Мост построили» — пассив: was built."},{id:"br-was-talking",type:"reorder",words:["she","was","talking","to","a","client","when","we","called"],alt:[["when","we","called","she","was","talking","to","a","client"],["we","called","when","she","was","talking","to","a","client"],["when","she","was","talking","to","a","client","we","called"]],rule:"was/were + -ing: in progress at a past moment",explain:"Was + -ing shows an action in progress when something else happened. The short action (called) is past simple, with no was.",ruHint:"«Она говорила с клиентом, когда мы позвонили» — was talking, но called без was."},{id:"br-what-happened",type:"errorTap",sentence:"What is happened? Everyone looks so worried.",wrong:1,correct:"What happened? Everyone looks so worried.",rule:"happen is never passive: What happened?",explain:"Nobody can 'happen' something, so happen has no passive and no be + V3. Say What happened? or What has happened? (has, not is).",ruHint:"«Что случилось?» — What happened? или What has happened?, но не is."}]},{id:"present-simple",group:"present",name:"Present Simple",ruName:"Настоящее простое",short:"Habits, facts, timetables and states: I work, she works.",idea:"Present simple — это не «прямо сейчас», а «так бывает вообще»: привычки, факты, расписания и состояния. Представь, что рассказываешь о своей жизни или о том, как устроен мир: I work in IT, the shop opens at 9, I don't eat meat. Главная ловушка — he/she/it: в утверждении глагол получает -s (she works), а в вопросах и отрицаниях появляется does/doesn't, и -s с глагола уходит (Does she work?).",category:"tense-choice",forms:[{label:"+",parts:["I / you / we / they","V1"],example:"We **live** near the park."},{label:"+ he/she/it",parts:["he / she / it","V1 + -s / -es"],example:"She **works** in IT and **goes** to the gym a lot."},{label:"−",parts:["I / you / we / they","don't","V1"],example:"I **don't eat** meat."},{label:"− he/she/it",parts:["he / she / it","doesn't","V1"],example:"He **doesn't drive**."},{label:"?",parts:["Do","I / you / we / they","V1?"],example:"**Do** you **speak** German?"},{label:"? he/she/it",parts:["Does","he / she / it","V1?"],example:"Where **does** she **work**?"}],timeline:{marks:[{kind:"repeat",at:-.9,to:.9,label:"I go to the gym"},{kind:"point",at:.5,label:"The train leaves at 7"}],caption:"Habits and facts are true before now, now and after now."},uses:[{en:"Habits and routines",ru:"То, что повторяется: каждый день, по пятницам, обычно. Важно не «сейчас», а «как обычно бывает».",example:{en:"I **check** my email first thing every morning.",ru:"Каждое утро я первым делом проверяю почту."}},{en:"Facts and permanent situations",ru:"Факты о мире и о тебе, которые не меняются в ближайшее время: где живёшь, где работаешь, что умеешь.",example:{en:"My brother **lives** in Novosibirsk and **works** as a developer.",ru:"Мой брат живёт в Новосибирске и работает разработчиком."}},{en:"Timetables and schedules",ru:"Расписания и графики (поезд, рейс, урок, магазин) — даже про будущее. В главном предложении present simple о будущем — только для расписаний; личные планы — present continuous или going to.",example:{en:"Our flight **leaves** at 6:40 tomorrow morning.",ru:"Наш рейс вылетает завтра в 6:40 утра."}},{en:"State verbs",ru:"Глаголы состояния (know, like, want, need, believe, belong, understand) обычно стоят в простом времени, даже если речь о «прямо сейчас».",example:{en:"We **need** a bigger flat, but we **don't want** to move.",ru:"Нам нужна квартира побольше, но переезжать мы не хотим."}},{en:"Future after when / if",ru:"В придаточных времени и условия (when, if, as soon as, before, until) будущее выражается present simple, will там не ставим. Но если when — это вопрос «когда?» (I don't know when he'll come), will нужен.",example:{en:"Let's go out as soon as the rain **stops**.",ru:"Пойдём гулять, как только кончится дождь."}}],signals:[{word:"always, usually, often",note:"стоят перед глаголом, но после be: She often works late, но She's often late"},{word:"sometimes, rarely, never",note:"never уже отрицание: I never eat meat, без don't"},{word:"every day, every summer"},{word:"on Mondays, at weekends",note:"at weekends — британский вариант, on weekends — американский"},{word:"once a week, twice a year",note:"обычно в конце фразы"},{word:"at 7:15 (timetable)",note:"расписание, даже о будущем: The bus leaves at 7:15"},{word:"as a rule, in general"},{word:"when, if, as soon as (future)",note:"в придаточном о будущем — present simple: when I get home (но I don't know when he'll come)"}],versus:[{tense:"present-continuous",ru:"Simple — постоянно или по привычке, «так у неё устроено». Continuous — временно или прямо сейчас: только на этой неделе.",a:{en:"She **works** from home on Fridays.",ru:"По пятницам она работает из дома."},b:{en:"She'**s working** from home this week.",ru:"На этой неделе она работает из дома."}},{tense:"present-perfect",ru:"Просто факт о настоящем — present simple. Как только появляется «с какого времени» или «как долго» (since, for, how long), нужен present perfect: «живу с 2019» = I've lived (или I've been living) here since 2019.",a:{en:"I **live** in Kazan.",ru:"Я живу в Казани."},b:{en:"I'**ve lived** in Kazan since 2019.",ru:"Я живу в Казани с 2019 года."}},{tense:"future-simple",ru:"После when, if, as soon as о будущем — present simple (when I get home). В главной части предложения о будущем — will или другая форма будущего.",a:{en:"I'll call you when I **get** home.",ru:"Позвоню, когда доберусь до дома."},b:{en:"I'**ll get** home around nine.",ru:"Доберусь до дома около девяти."}}],mistakes:[{wrong:"He work in a bank.",right:"He works in a bank.",why:"С he/she/it в утверждении к глаголу добавляется -s: проверь, кто подлежащее."},{wrong:"Where you live?",right:"Where do you live?",why:"Вопрос в present simple строится с do/does перед подлежащим, без помощника вопроса нет."},{wrong:"She don't eat meat.",right:"She doesn't eat meat.",why:"С he/she/it отрицание — doesn't, а don't только с I/you/we/they."},{wrong:"Does he speaks English?",right:"Does he speak English?",why:"Does уже забрал -s себе, поэтому после does/doesn't глагол всегда в V1, без -s."},{wrong:"What means this word?",right:"What does this word mean?",why:"Порядок слов как в русском «что значит» не работает: в вопросе нужен does перед подлежащим, а глагол — без -s."},{wrong:"I meet Anna tonight.",right:"I'm meeting Anna tonight.",why:"Present simple о будущем берут для расписаний (и после when/if), а личную договорённость — present continuous."}],trick:"Правило одной -s: с he/she/it в present simple «эс» появляется ровно один раз — или на глаголе (She works), или на помощнике (Does she work? She doesn't work). Две сразу (Does she works) — ошибка, ни одной (She work) — тоже. Модальные глаголы (can, must, should) живут по своим правилам: she can, без -s.",examples:[{en:"I **start** work at nine, but I usually **get** to the office earlier.",ru:"Я начинаю работать в девять, но обычно прихожу в офис раньше."},{en:"Kate **teaches** English online and **travels** a lot.",ru:"Кейт преподаёт английский онлайн и много путешествует."},{en:"**Do** you **know** where the nearest pharmacy is?",ru:"Ты не знаешь, где ближайшая аптека?"},{en:"He **doesn't drink** coffee after six.",ru:"Он не пьёт кофе после шести."},{en:"The last train to the airport **leaves** at 23:40.",ru:"Последний поезд в аэропорт уходит в 23:40."},{en:"How often **does** your team **have** meetings?",ru:"Как часто у твоей команды встречи?"},{en:"We **don't need** a car because we **live** near the metro.",ru:"Нам не нужна машина: мы живём рядом с метро."},{en:"**Does** this charger **belong** to you?",ru:"Это твоя зарядка?"},{en:"My parents **visit** us twice a year.",ru:"Родители приезжают к нам два раза в год."},{en:"What time **does** the museum **open** on Sundays?",ru:"Во сколько музей открывается по воскресеньям?"}],exercises:[{id:"ps-brother-works",type:"fill",before:"My brother usually ",after:" from home on Fridays, but today he's in the office.",answers:["works"],base:"work",rule:"he / she / it + V1 + -s",explain:"Usually shows a regular habit that is still true now (today is the exception), so use present simple. With he, she or it, add -s: works.",ruHint:"С he/she/it добавь -s: works."},{id:"ps-doesnt-like",type:"choice",prompt:"My manager ___ long meetings, so ours are always short.",options:["don't like","doesn't like","doesn't likes","isn't like"],answer:1,rule:"he / she / it: doesn't + V1 (no -s)",explain:"With he, she or it, the negative is doesn't, and the verb loses its -s: doesn't like.",ruHint:"С he/she/it — doesn't + глагол без -s."},{id:"ps-where-does",type:"reorder",words:["where","does","your","sister","work"],end:"?",rule:"Question: where + does + he/she + V1",explain:"Present simple questions need do or does before the subject. Your sister is she, so use does, and the verb has no -s: work.",ruHint:"«Где работает твоя сестра?» — Where does … work?"},{id:"ps-dont-know",type:"choice",prompt:"Sorry, I ___ his phone number. Ask Max.",options:["don't know","am not knowing","not know","doesn't know"],answer:0,rule:"State verbs (know, want, need) → present simple",explain:"Know is a state verb, so it stays in present simple even when you mean now: I don't know.",ruHint:"know — глагол состояния: I don't know."},{id:"ps-does-work",type:"errorTap",sentence:"Does Anna works on Saturdays?",wrong:2,correct:"Does Anna work on Saturdays?",rule:"After does / doesn't: V1 without -s",explain:"Does already carries the -s, so the main verb stays in the base form: Does Anna work…?",ruHint:"После does — глагол без -s."},{id:"ps-when-get-home",type:"fill",before:"I'll text you when I ",after:" to the office.",answers:["get","have got","have gotten"],base:"get",rule:"when / if + present for the future (no will)",explain:"In a time clause after when, if or as soon as, use present simple for the future, not will: when I get to the office.",ruHint:"После when про будущее — present simple: when I get to the office."},{id:"ps-plans-saturday",type:"choice",prompt:"What ___ this Saturday? Want to go hiking with us?",options:["do you do","you are doing","are you doing","do you doing"],answer:2,rule:"Personal plans → be + -ing, not present simple",explain:"You are asking about plans, so use present continuous: What are you doing…? 'What do you do?' asks about someone's job.",ruHint:"Про планы — What are you doing…?"},{id:"ps-lived-since",type:"errorTap",sentence:"We live in this flat since 2021.",wrong:1,correct:"We have lived in this flat since 2021.",rule:"since + a start point → present perfect",explain:"Since 2021 shows a period from the past up to now, so English uses present perfect: have lived (or have been living). Russian uses the present here, English doesn't.",ruHint:"«Живём с 2021» — have lived since 2021."}]},{id:"present-continuous",group:"present",name:"Present Continuous",ruName:"Настоящее длительное",short:"Now, around now, temporary or changing; also fixed plans for the future.",idea:"Present continuous — это «кадр из видео»: действие уже началось, ещё не закончилось и идёт прямо сейчас или в этот период жизни (this week, these days). Поэтому им говорят о временном и меняющемся: I'm working from home this week, prices are going up. А ещё — о будущем, которое уже договорено и стоит в календаре: I'm meeting Anna tomorrow.",category:"tense-choice",forms:[{label:"+",parts:["I","am ('m)","V-ing"],example:"I'**m working** on a new app."},{label:"+ he/she/it",parts:["he / she / it","is ('s)","V-ing"],example:"She'**s talking** to a client."},{label:"+ you/we/they",parts:["you / we / they","are ('re)","V-ing"],example:"We'**re waiting** for the bus."},{label:"−",parts:["subject","am not / isn't / aren't","V-ing"],example:"He **isn't listening** to me."},{label:"?",parts:["Am / Is / Are","subject","V-ing?"],example:"**Are** you **coming** to the party?"}],timeline:{marks:[{kind:"span",at:-.25,to:.25,label:"I'm working right now"},{kind:"point",at:.6,label:"I'm meeting Anna"}],caption:"Started before now and not finished yet, or already arranged for later."},uses:[{en:"Happening right now",ru:"Действие идёт в момент речи: уже началось и ещё не закончилось.",example:{en:"Can I call you back? I'**m driving**.",ru:"Можно я перезвоню? Я за рулём."}},{en:"Around now, temporary",ru:"Не обязательно в эту секунду: что-то происходит в этот период (на этой неделе, в этом году) и не навсегда. Сравни: I live in Kazan (постоянно) и I'm living with my parents for now (временно).",example:{en:"I'**m learning** Spanish this year, and it'**s going** well.",ru:"В этом году я учу испанский, и всё идёт неплохо."}},{en:"Changing situations",ru:"Что-то постепенно меняется: растёт, падает, становится лучше или хуже. Часто с get, rise, more and more.",example:{en:"Rents in Moscow **are going up** again.",ru:"Аренда в Москве снова растёт."}},{en:"Fixed plans for the future",ru:"Договорённость: уже решено и организовано, есть время, место, билет или встреча в календаре. Обычно рядом указано время (tomorrow, on Friday) или оно понятно из контекста.",example:{en:"I'**m meeting** Anna for lunch tomorrow.",ru:"Завтра я обедаю с Анной."}},{en:"always: annoying habit",ru:"Always или constantly + -ing — обычно эмоция, чаще раздражение: «вечно он…». Нейтральная привычка без эмоций — present simple: He always calls on Sundays.",example:{en:"He'**s always losing** his keys!",ru:"Он вечно теряет ключи!"}}],signals:[{word:"now, right now"},{word:"at the moment, currently"},{word:"Look! / Listen!",note:"показывают на то, что происходит прямо сейчас"},{word:"today, this week, this month",note:"временный период: I'm working from home this week"},{word:"these days",note:"в последнее время: временное или меняющееся"},{word:"still",note:"ещё не закончилось: Are you still waiting?"},{word:"more and more, getting + -er",note:"изменение: It's getting colder"},{word:"tonight, tomorrow, on Friday",note:"с договорённостью это будущее: I'm flying to Baku on Friday"},{word:"always, constantly",note:"+ -ing = раздражение («вечно он…»); простая привычка — present simple"}],versus:[{tense:"present-simple",ru:"Continuous — идёт сейчас или временно. Simple — привычка, «вообще так бывает».",a:{en:"He'**s playing** tennis right now.",ru:"Он сейчас играет в теннис."},b:{en:"He **plays** tennis every Sunday.",ru:"Он играет в теннис каждое воскресенье."}},{tense:"present-simple",ru:"Think в значении «обдумываю» — действие, можно -ing; в значении «считаю» — состояние, только simple. Так же have (I'm having lunch / I have a car) и see (I'm seeing a client / I see what you mean).",a:{en:"I'**m thinking** about a new job.",ru:"Я подумываю о новой работе."},b:{en:"I **think** it's a great job.",ru:"По-моему, это отличная работа."}},{tense:"going-to",ru:"Continuous — план уже организован: есть дата, договор, билет. Going to — намерение: решение есть, а договорённости может и не быть. Если всё уже организовано, часто подходят оба.",a:{en:"We'**re moving** to Kazan in May.",ru:"В мае мы переезжаем в Казань."},b:{en:"We'**re going to move** to Kazan, but we don't know when yet.",ru:"Мы собираемся переехать в Казань, но пока не знаем когда."}}],mistakes:[{wrong:"Don't call me now, I drive.",right:"Don't call me now, I'm driving.",why:"Действие идёт прямо в момент речи, поэтому нужен am/is/are + -ing."},{wrong:"Hi! Where do you go?",right:"Hi! Where are you going?",why:"Человек уже идёт, действие в процессе; Where do you go? значит «куда ты обычно ходишь»."},{wrong:"She working from home today.",right:"She's working from home today.",why:"Без am/is/are форма на -ing не работает: проверь, есть ли be перед глаголом с -ing."},{wrong:"Sorry, I'm not understanding the question.",right:"Sorry, I don't understand the question.",why:"Understand — глагол состояния: даже про «прямо сейчас» говорим I don't understand, без -ing."},{wrong:"I meet my friends tonight.",right:"I'm meeting my friends tonight.",why:"Договорённость на вечер — present continuous; present simple о будущем только для расписаний."},{wrong:"I'm thinking you're right.",right:"I think you're right.",why:"Think в значении «считаю, по-моему» — состояние, без -ing; I'm thinking значит «обдумываю»."}],trick:"Фишка «видео на паузе»: если можно нажать паузу посреди действия (оно уже началось и ещё не закончилось), бери am/is/are + -ing. Знание, желание, симпатию (know, want, like, need) на паузу не поставишь — это состояния, поэтому обычно I know, а не I'm knowing. Think, have, see получают -ing, только когда это действие: I'm thinking = обдумываю, I'm having lunch = обедаю, I'm seeing a client = встречаюсь.",examples:[{en:"Shh, the kids **are sleeping**.",ru:"Тише, дети спят."},{en:"Our team **is testing** a new version of the app this week.",ru:"На этой неделе наша команда тестирует новую версию приложения."},{en:"**Are** you **waiting** for someone?",ru:"Ты кого-то ждёшь?"},{en:"She **isn't working** today because she's ill.",ru:"Сегодня она не работает, потому что болеет."},{en:"Flights to Turkey **are getting** more expensive every year.",ru:"Перелёты в Турцию дорожают с каждым годом."},{en:"I'**m flying** to Yerevan on Friday, and the hotel is already booked.",ru:"В пятницу я лечу в Ереван, отель уже забронирован."},{en:"What **are** you **doing** tonight? Want to grab a pizza?",ru:"Что делаешь вечером? Может, сходим за пиццей?"},{en:"My neighbour **is always playing** the drums at midnight!",ru:"Сосед вечно играет на барабанах в полночь!"},{en:"I'**m thinking** about changing jobs, but nothing is decided yet.",ru:"Подумываю сменить работу, но пока ничего не решено."},{en:"They'**re having** lunch, so call them in an hour.",ru:"Они обедают, так что позвони им через час."}],exercises:[{id:"pc-giving-presentation",type:"choice",prompt:"Sorry, can you call back later? I ___ a presentation right now.",options:["give","am giving","giving","am give"],answer:1,rule:"Right now → am/is/are + -ing",explain:"The action is in progress at this moment, so use present continuous: am giving. 'I give' is for habits.",ruHint:"Прямо сейчас — am giving."},{id:"pc-is-working",type:"fill",before:"Anna can't talk now. She ",after:" on an urgent bug.",answers:["is working"],base:"work",rule:"Now → is + -ing: she is working",explain:"'Now' shows an action in progress, so use is + -ing. Don't forget is: 'She working' has no tense.",ruHint:"Не забудь is: she is working."},{id:"pc-max-studying",type:"errorTap",sentence:"Please be quiet. Max studies for an exam in the next room.",wrong:4,correct:"Please be quiet. Max is studying for an exam in the next room.",rule:"In progress now → be + -ing, not present simple",explain:"Max is studying at this moment, and that's why we must be quiet. So use present continuous: is studying.",ruHint:"Действие идёт прямо сейчас — is studying."},{id:"pc-meeting-sister",type:"fill",before:"Kate called back, and it's all arranged: we ",after:" for coffee at five tomorrow.",answers:["are meeting","are going to meet","will be meeting","will meet"],base:"meet",rule:"Fixed arrangement → am/is/are + -ing",explain:"It's arranged: you know the time and the place. For fixed plans, English usually uses present continuous: we're meeting. 'We meet' is wrong here.",ruHint:"Уже договорились на завтра — we're meeting."},{id:"pc-see-what-you-mean",type:"choice",prompt:"I ___ what you mean, but I still don't agree.",options:["am seeing","am understanding","see","seeing"],answer:2,rule:"see = understand → state verb, no -ing",explain:"Here see means understand, a state, so it stays in present simple: I see. 'I'm seeing a client' is an action: I'm meeting someone.",ruHint:"see в значении «понимаю» — без -ing."},{id:"pc-thinking-of",type:"choice",prompt:"We ___ of moving to Georgia next year. What do you think?",options:["think","are thinking","thinks","are think"],answer:1,rule:"think = consider → -ing is fine",explain:"Here think means consider, an action in progress, so use are thinking. Think for an opinion stays simple: What do you think?",ruHint:"«Подумываем» — are thinking; «по-моему» — think."},{id:"pc-always-interrupting",type:"reorder",words:["why","are","you","always","interrupting","me"],end:"?",rule:"always + -ing = an annoying habit",explain:"Always with present continuous shows that a habit annoys you. Always goes between are and the -ing verb.",ruHint:"«Ну почему ты вечно меня перебиваешь?» — are always interrupting."},{id:"pc-getting-colder",type:"fill",before:"It's November, and it ",after:" colder and colder.",answers:["is getting","has been getting","keeps getting"],base:"get",rule:"Change in progress → be + -ing",explain:"Colder and colder shows a change that is still going on, so use present continuous: is getting. 'Keeps getting' also works.",ruHint:"Постепенное изменение — is getting."}]},{id:"present-perfect",group:"present",name:"Present Perfect",ruName:"Настоящее совершённое",short:"The past linked to now: a result, an experience, or a state up to now",idea:"В русском такого времени нет: в «ключи потерялись» и «ключи потерялись вчера» глагол один и тот же, а в английском это два разных времени — I've lost my keys и I lost my keys yesterday. Present perfect — мост из прошлого в сейчас: когда именно это случилось, неважно, важно, что есть сейчас — результат, опыт или итог за период, который ещё идёт. Как только появляется законченное «когда» (вчера, в 2020 году, неделю назад), мост рушится и нужен past simple.",category:"perfect",forms:[{label:"+",parts:["I / you / we / they","have ('ve)","V3"],example:"We'**ve finished** the report."},{label:"+ he/she/it",parts:["he / she / it","has ('s)","V3"],example:"She **has** already **left**."},{label:"−",parts:["subject","haven't / hasn't","V3"],example:"I **haven't seen** the new season yet."},{label:"?",parts:["Have / Has","subject","V3?"],example:"**Have** you ever **been** to Japan?"},{label:"V3",parts:["regular: V1 + -ed","go → gone","see → seen","do → done"],example:"I'**ve seen** the film, but I'**ve** never **read** the book."}],timeline:{marks:[{kind:"result",at:-.6,to:0,label:"I've lost my keys"}],caption:"It happened before now, and the result matters now."},uses:[{en:"Result now",ru:"Что-то случилось раньше, а важно, что из этого вышло сейчас. Когда именно — не говорим и не спрашиваем.",example:{en:"I'**ve lost** my keys, so I can't get into the flat.",ru:"У меня пропали ключи — не могу попасть в квартиру."}},{en:"Life experience",ru:"Опыт за всю жизнь до сегодняшнего дня: было такое хоть раз или нет. Часто с ever, never, before, twice.",example:{en:"**Have** you ever **been** to a hockey match?",ru:"Тебе доводилось бывать на хоккейном матче?"}},{en:"Unfinished time period",ru:"Период ещё не закончился: today, this week, this year, so far. Пока он идёт, итог ещё может измениться.",example:{en:"She'**s been** to the gym twice this week.",ru:"На этой неделе она уже два раза ходила в спортзал."}},{en:"From then until now",ru:"Состояние началось в прошлом и длится до сих пор: since + момент начала, for + срок. По-русски тут настоящее время («знакомы со школы»), а по-английски — have + V3.",example:{en:"We'**ve known** each other since school.",ru:"Мы знакомы со школы."}},{en:"Just, already, yet",ru:"Свежие новости и ожидания: just — только что, already — уже (раньше, чем ждали), yet — «уже?» в вопросах и «ещё не» в отрицаниях. В американском английском с этими словами часто говорят и past simple (I just saw it), это тоже норма.",example:{en:"We **haven't booked** the hotel yet.",ru:"Мы ещё не забронировали отель."}}],signals:[{word:"ever",note:"хоть раз в жизни: Have you ever…?, the best film I've ever seen"},{word:"never",note:"never + V3, без not: I've never been there"},{word:"just",note:"между have и V3: I've just arrived"},{word:"already",note:"обычно между have и V3: She's already paid"},{word:"yet",note:"в вопросах и отрицаниях, в конце фразы"},{word:"since 2020, since Monday",note:"since + момент начала, до сих пор"},{word:"for two years",note:"for + срок до сих пор; если период уже закончился — past simple: I lived there for two years"},{word:"today, this week, this year",note:"только пока период не закончился"},{word:"so far, recently, lately",note:"к этому моменту, в последнее время; recently бывает и с past simple: I recently moved"},{word:"How long…?",note:"сколько длится до сих пор: How long have you known her?"}],versus:[{tense:"past-simple",ru:"Present perfect — опыт или результат к сегодняшнему дню, время не названо. Как только появляется законченное «когда» (in 2019, last summer), нужен past simple.",a:{en:"We'**ve been** to Rome twice.",ru:"Мы были в Риме дважды."},b:{en:"We **went** to Rome in 2019.",ru:"Мы ездили в Рим в 2019 году."}},{tense:"present-perfect-continuous",ru:"Have + V3 — результат: сколько сделано (три письма). Have been + -ing — процесс: чем человек занят и сколько времени (всё утро).",a:{en:"She'**s written** three emails this morning.",ru:"Она с утра уже написала три письма."},b:{en:"She'**s been writing** emails all morning.",ru:"Она всё утро пишет письма."}},{tense:"present-simple",ru:"Present simple — просто факт сейчас. Как только говоришь, сколько это длится до сих пор (How long…?, for, since), нужен present perfect, хотя по-русски глагол в настоящем времени.",a:{en:"How long **have** you **lived** in Berlin?",ru:"Сколько ты уже живёшь в Берлине?"},b:{en:"**Do** you **live** in Berlin?",ru:"Ты живёшь в Берлине?"}}],mistakes:[{wrong:"I have finished the project last week.",right:"I finished the project last week.",why:"Last week — законченное время: если во фразе есть «когда» из прошлого, убирай have и ставь past simple."},{wrong:"I know him for five years.",right:"I've known him for five years.",why:"«Знаю пять лет» — срок до сих пор: когда for или since считают время до сейчас, present simple не годится, нужен have + V3."},{wrong:"When have you arrived?",right:"When did you arrive?",why:"When спрашивает о законченном моменте, поэтому вопрос строится с did, а не с have."},{wrong:"I'm here since Monday.",right:"I've been here since Monday.",why:"Since значит «с того момента и до сих пор», поэтому am превращается в have been."},{wrong:"Anna isn't here. She has been to the bank.",right:"Anna isn't here. She has gone to the bank.",why:"Been — сходила и вернулась, gone — ушла и ещё не вернулась; раз Анны нет на месте, нужно gone."},{wrong:"He has went home.",right:"He has gone home.",why:"После have/has всегда V3, а не V2: go – went – gone."}],trick:"Тест «окно открыто?»: представь период, к которому относится событие. Окно закрыто (yesterday, in 2020, last week, when I was a child) — past simple; окно ещё открыто (today, this year, за всю жизнь, since…) или время вообще не важно, а важен итог сейчас — present perfect. Даже this morning работает так: в 10 утра — I've had two coffees this morning, а в 3 часа дня утро уже прошло — I had two coffees this morning.",examples:[{en:"She **has worked** at this school since 2015.",ru:"Она работает в этой школе с 2015 года."},{en:"**Have** you ever **worked** with Python?",ru:"У тебя есть опыт работы с Python?"},{en:"We'**ve** just **sent** you the invoice.",ru:"Мы только что отправили вам счёт."},{en:"I'**ve** already **booked** the tickets, so don't worry.",ru:"Билеты уже забронированы, не переживай."},{en:"He **hasn't called** me since our argument.",ru:"Он не звонил мне с тех пор, как мы поссорились."},{en:"**Has** Max **finished** the presentation yet?",ru:"Макс уже закончил презентацию?"},{en:"We'**ve had** three releases this month, and it's only the 20th.",ru:"В этом месяце у нас уже три релиза, а сегодня только двадцатое."},{en:"Sergey **has gone** to Turkey for a week, so call Olga instead.",ru:"Сергей уехал в Турцию на неделю, так что звони Ольге."},{en:"My kids **have never been** on a plane.",ru:"Мои дети ещё ни разу не летали на самолёте."},{en:"How long **have** you **known** each other?",ru:"Сколько вы уже знакомы?"}],exercises:[{id:"pperf-ever-eaten",type:"choice",prompt:"Have you ever ___ Georgian food?",options:["eat","ate","eaten","eating"],answer:2,rule:"have + V3: eat → ate → eaten",explain:"After have you need V3, the third form. For eat it is eaten: Have you ever eaten…?",ruHint:"После have — V3: eaten."},{id:"pperf-lived-since",type:"fill",before:"My sister ",after:" in Kazan since 2019, and she loves it.",answers:["has lived","has been living"],base:"live",rule:"since + start point → has/have + V3",explain:"She started living there in 2019 and still lives there, so use present perfect: has lived. Present simple (lives) can't go with since.",ruHint:"«Живёт с 2019 года» — has lived, а не lives."},{id:"pperf-met-in-2019",type:"choice",prompt:"I ___ Max at a conference in 2019, and we're still friends.",options:["have met","met","have meet","meet"],answer:1,rule:"Finished time (in 2019) → past simple",explain:"In 2019 is a finished time, so use past simple: met. 'We're still friends' doesn't change that: the meeting itself is over.",ruHint:"С in 2019 — только past simple, даже если дружба продолжается."},{id:"pperf-been-supermarket",type:"choice",prompt:"I'm back! I ___ to the supermarket. Here's your milk.",options:["have gone","have been","has been","am gone"],answer:1,rule:"been = went and came back; gone = still there",explain:"You are back, so the trip is over: have been. 'Have gone' would mean you are still at the supermarket.",ruHint:"Сходить и вернуться — been, уйти и ещё не вернуться — gone."},{id:"pperf-has-gone-home",type:"errorTap",sentence:"Tom isn't here — he has went home with a headache.",wrong:6,correct:"Tom isn't here — he has gone home with a headache.",rule:"have/has + V3: go → went → gone",explain:"After has you need V3. Went is V2; the V3 of go is gone.",ruHint:"После has — V3: gone, а не went (V2)."},{id:"pperf-finished-yet",type:"reorder",words:["have","you","finished","the","report","yet"],end:"?",rule:"Question: have + subject + V3; yet goes at the end",explain:"A present perfect question: have + you + V3. Yet means 'already?' in questions and goes at the end.",ruHint:"«Отчёт уже готов?» — have в начале, yet в конце."},{id:"pperf-known-for",type:"fill",before:"I ",after:" Max for ten years, and he's never been late.",answers:["have known"],base:"know",rule:"for + period up to now → have + V3",explain:"You still know him, and 'for ten years' counts up to now: have known. 'I know him for ten years' copies the Russian present.",ruHint:"«Знаю десять лет» — I have known, а не I know."},{id:"pperf-how-long-company",type:"choice",prompt:"You know everyone here! How long ___ at this company?",options:["do you work","are you working","have you worked","you have worked"],answer:2,rule:"How long … up to now → have + V3, not present",explain:"The question is about the time from the start until now, so use present perfect: How long have you worked…? 'Have you been working' is also correct.",ruHint:"«Сколько ты здесь работаешь?» — How long have you worked…?"}]},{id:"present-perfect-continuous",group:"present",name:"Present Perfect Continuous",ruName:"Настоящее совершённое длительное",short:"An activity from the past up to now, or one that has just stopped",idea:"Это время про процесс, который начался в прошлом и тянется до сейчас — или только что закончился, и следы ещё видны. Тебя интересует не результат, а сама деятельность и сколько времени она идёт. По-русски говорят «я работаю здесь пять лет» в настоящем времени, а в английском это отрезок от прошлого до сейчас: I've been working here for five years.",category:"perfect",forms:[{label:"+",parts:["I / you / we / they","have been","V-ing"],example:"We'**ve been waiting** for an hour."},{label:"+ he/she/it",parts:["he / she / it","has been","V-ing"],example:"It'**s been raining** since this morning."},{label:"−",parts:["subject","haven't / hasn't been","V-ing"],example:"He **hasn't been feeling** well."},{label:"?",parts:["Have / Has","subject","been","V-ing?"],example:"**Have** they **been working** late again?"},{label:"How long?",parts:["How long","have / has","subject","been","V-ing?"],example:"How long **has** she **been working** here?"}],timeline:{marks:[{kind:"span",at:-.7,to:0,label:"working here for 5 years"}],caption:"It started in the past and is still going on now."},uses:[{en:"Still going on now",ru:"Действие началось в прошлом и идёт до сих пор, а ты считаешь, сколько времени: for, since, How long. С work, live, teach, study подойдёт и have + V3 (I've worked here for five years) — разница минимальна.",example:{en:"I'**ve been working** here since March.",ru:"Я работаю здесь с марта."}},{en:"Just stopped, visible traces",ru:"Процесс только что закончился, а следы видны: усталость, мокрые улицы, краска на руках. Важна сама деятельность, а не результат.",example:{en:"You look tired. **Have** you **been running**?",ru:"У тебя усталый вид. С пробежки?"}},{en:"Repeated lately",ru:"То, чем человек занят в последнее время: повторяется или длится временно и ещё не закончилось.",example:{en:"We'**ve been eating** out a lot lately.",ru:"В последнее время мы часто едим вне дома."}}],signals:[{word:"for + period",note:"for two hours, for years — сколько уже длится"},{word:"since + start point",note:"since 9 a.m., since Monday, since we moved"},{word:"How long…?",note:"главный вопрос этого времени: How long have you been…?"},{word:"all day, all morning, all week",note:"акцент на процессе и его длительности"},{word:"lately, recently",note:"в последнее время: I've been sleeping badly lately"},{word:"You look tired… / Why are you wet?",note:"видны следы недавнего процесса — спроси про него: Have you been…?"}],versus:[{tense:"present-perfect",ru:"Have been + -ing — процесс и сколько времени он занял (может, ещё не закончили). Have + V3 — готовый результат: кухня покрашена.",a:{en:"We'**ve been painting** the kitchen all weekend.",ru:"Мы все выходные красим кухню."},b:{en:"We'**ve painted** the kitchen.",ru:"Мы покрасили кухню."}},{tense:"present-continuous",ru:"Present continuous — что происходит сейчас, без «сколько уже». Добавляешь «сколько уже» (for, since, How long…?) — и нужен have been + -ing.",a:{en:"I'**ve been waiting** for my coffee for ten minutes.",ru:"Я жду свой кофе уже десять минут."},b:{en:"I'**m waiting** for my coffee.",ru:"Я жду свой кофе."}},{tense:"present-simple",ru:"Present simple — просто факт: чем человек занимается. Если считаешь время от начала до сейчас (for ten years), нужен have been + -ing или have + V3, хотя по-русски в обоих случаях «преподаёт».",a:{en:"She'**s been teaching** yoga for ten years.",ru:"Она преподаёт йогу десять лет."},b:{en:"She **teaches** yoga.",ru:"Она преподаёт йогу."}}],mistakes:[{wrong:"I work here for five years.",right:"I've been working here for five years.",why:"«Работаю пять лет» — срок до сейчас: когда for или since считают время до сейчас, present simple не ставят."},{wrong:"I'm learning English since 2022.",right:"I've been learning English since 2022.",why:"Am/is/are + -ing показывает только «сейчас»; если есть since или for, нужно have been + -ing."},{wrong:"How long are you waiting?",right:"How long have you been waiting?",why:"«Сколько уже ждёшь» — это отрезок до сейчас, а How long are you…? спрашивает о планах (How long are you staying?)."},{wrong:"We've been knowing each other for years.",right:"We've known each other for years.",why:"Know — глагол состояния, в -ing его не ставят: для know, like, own, be бери have + V3."},{wrong:"I've been writing three reports today.",right:"I've written three reports today.",why:"Если считаешь, сколько сделано (три отчёта), нужен результат: have + V3, а не процесс."},{wrong:"I've been waiting since two hours.",right:"I've been waiting for two hours.",why:"Since — с какого момента (since 3 o'clock), for — сколько времени (for two hours): «уже два часа» — это for."}],trick:"Спроси себя: «сколько времени?» или «сколько штук?». Сколько времени идёт процесс (for two hours, all day, since May) — have been + -ing: I've been writing emails all day; сколько сделано (three emails, twice) — have + V3: I've written three emails. Глаголы состояния (know, be, own) остаются в have + V3 даже с for: I've known her for years.",examples:[{en:"She'**s been working** at the bank since 2021.",ru:"Она работает в банке с 2021 года."},{en:"We'**ve been waiting** for the train for forty minutes.",ru:"Мы ждём поезд уже сорок минут."},{en:"How long **have** you **been living** in this flat?",ru:"Сколько ты уже живёшь в этой квартире?"},{en:"It'**s been raining** all day, so we're staying in.",ru:"Весь день идёт дождь, так что мы сидим дома."},{en:"Your hands are dirty. **Have** you **been fixing** the bike?",ru:"У тебя грязные руки. Ты что, велосипед чинишь?"},{en:"I **haven't been sleeping** well lately.",ru:"В последнее время я плохо сплю."},{en:"They'**ve been arguing** about the budget since Monday.",ru:"Они спорят о бюджете с понедельника."},{en:"**Has** Alex **been working** from home this week?",ru:"Алекс на этой неделе работает из дома?"},{en:"Our designers **have been working** on the new logo for two weeks.",ru:"Наши дизайнеры уже две недели работают над новым логотипом."},{en:"Sorry I'm late! **Have** you **been waiting** long?",ru:"Извини за опоздание! Долго ждёшь?"}],exercises:[{id:"ppc-waiting-bus",type:"choice",prompt:"We ___ for the bus for twenty minutes. Where is it?",options:["are waiting","wait","have been waiting","were waiting"],answer:2,rule:"for + still going on → have been + -ing",explain:"The waiting started twenty minutes ago and is still going on, so use have been waiting. 'Are waiting' can't go with for + a period up to now.",ruHint:"«Ждём уже двадцать минут» — have been waiting."},{id:"ppc-yoga-for",type:"fill",before:"Lena ",after:" yoga for ten years, so she's very flexible.",answers:["has been doing","has done"],base:"do",rule:"for + activity up to now → has been + -ing",explain:"She started ten years ago and still does yoga: has been doing. 'Has done' is also fine here. 'Does yoga for ten years' is not English.",ruHint:"«Занимается десять лет» — has been doing, а не does."},{id:"ppc-how-long-learning",type:"choice",prompt:"Your English is great! How long ___ it?",options:["have you been learning","do you learn","are you learning","you have been learning"],answer:0,rule:"How long? (up to now) → have you been + -ing?",explain:"How long asks about the time from the start until now, so use have you been learning. In a question, have comes before you.",ruHint:"«Сколько ты уже учишь?» — How long have you been learning…?"},{id:"ppc-home-since-monday",type:"reorder",words:["she","has","been","working","from","home","since","Monday"],alt:[["since","Monday","she","has","been","working","from","home"]],rule:"has been + -ing … since + start point",explain:"Subject + has been + -ing, then the place and the time: since Monday.",ruHint:"«Она работает из дома с понедельника»."},{id:"ppc-learning-since",type:"fill",before:"I ",after:" English since 2022, and now I can watch films without subtitles.",answers:["have been learning"],base:"learn",rule:"since + ongoing activity → have been + -ing",explain:"Learning started in 2022 and is still going on, so use have been learning. Present simple (learn) can't go with since.",ruHint:"«Учу с 2022 года» — have been learning, а не learn."},{id:"ppc-living-since",type:"errorTap",sentence:"I am living in this city since 2015, and I love it.",wrong:1,correct:"I have been living in this city since 2015, and I love it.",rule:"since/for → have been + -ing, not am + -ing",explain:"Since 2015 means from then until now, so use have been living (or have lived). 'Am living' only shows now, not how long.",ruHint:"С since не бывает am + -ing — нужно have been living."},{id:"ppc-three-reports",type:"choice",prompt:"I ___ three reports today, and I'm exhausted.",options:["have been writing","have written","was writing","write"],answer:1,rule:"How many (a result) → have + V3, not been + -ing",explain:"Three reports is a number of finished things, a result. For how many, use have written. Have been writing is about how long.",ruHint:"Сколько штук сделано — have + V3: have written."},{id:"ppc-known-since",type:"choice",prompt:"We ___ each other since university.",options:["have been knowing","have known","know","are knowing"],answer:1,rule:"State verb know → have known, not been knowing",explain:"Know is a state verb, so it doesn't take -ing, even with since: have known.",ruHint:"know — глагол состояния: have known, а не have been knowing."}]},{id:"past-simple",group:"past",name:"Past Simple",ruName:"Простое прошедшее",short:"A finished action at a finished time in the past",idea:"Past simple — это законченное прошлое: действие случилось и закончилось, и время тоже закончилось — вчера, в 2019 году, неделю назад, в детстве. В утверждении прошлое показывает сам глагол (worked, went), а в вопросе и отрицании эту работу берёт на себя did, и глагол возвращается в V1: Did you go? I didn't go. Was/were — это прошедшее от be, для состояний (I was tired, it was cold); с обычным глаголом в past simple was не нужен: I went, а не I was go.",category:"tense-choice",forms:[{label:"+ regular",parts:["subject","V1 + -ed","stop → stopped","study → studied"],example:"We **worked** late yesterday."},{label:"+ irregular",parts:["subject","V2","go → went","have → had","see → saw","make → made"],example:"I **saw** Anna at the station."},{label:"−",parts:["subject","didn't","V1"],example:"She **didn't call** me back."},{label:"?",parts:["Did","subject","V1?"],example:"**Did** you **see** the match?"},{label:"was / were",parts:["I / he / she / it + was","you / we / they + were"],example:"I **was** tired, and the kids **were** hungry."},{label:"be: − and ?",parts:["wasn't / weren't","Was / Were + subject …?"],example:"**Were** you at work? No, I **wasn't**."}],timeline:{marks:[{kind:"span",at:-.85,to:-.45,label:"lived in Omsk 3 years"},{kind:"point",at:-.2,label:"moved to Kazan"}],caption:"Finished actions at finished times, cut off from now."},uses:[{en:"Finished time",ru:"Действие закончилось, и момент назван или понятен: yesterday, last year, in 2019, two days ago. Если есть законченное «когда», нужно прошедшее время, а не present perfect.",example:{en:"We **moved** to Kazan in 2019.",ru:"Мы переехали в Казань в 2019 году."}},{en:"A story, step by step",ru:"Цепочка событий в прошлом: каждое следующее — в past simple, по порядку, как кадры фильма.",example:{en:"He **got** up, **made** coffee and **opened** his laptop.",ru:"Он встал, сварил кофе и открыл ноутбук."}},{en:"Finished period",ru:"Состояние или привычка длились какое-то время, но уже закончились: for three years, from 2015 to 2020, в детстве. For здесь тоже бывает — главное, что период закрыт.",example:{en:"She **worked** in London for three years, then **came** back home.",ru:"Она три года работала в Лондоне, а потом вернулась домой."}},{en:"Past states: was / were",ru:"Was/were — прошедшее от be: для состояний, качеств и мест (tired, at home, a student). Перед обычным глаголом was не нужен: I went, а не I was go.",example:{en:"The hotel **was** nice, but the rooms **were** small.",ru:"Отель был хороший, но номера маленькие."}},{en:"When…? questions",ru:"When…? и What time…? о прошлом спрашивают о законченном моменте, поэтому нужен past simple: did + V1 (с be — was/were), а не have.",example:{en:"What time **did** the meeting **finish**?",ru:"Во сколько закончилась встреча?"}}],signals:[{word:"yesterday"},{word:"last week, last year, last night",note:"без the: last week = на прошлой неделе"},{word:"… ago",note:"two days ago, a year ago — прошедшее время, никогда не present perfect"},{word:"in 2019, in May",note:"дата в прошлом"},{word:"on Monday, at 5 o'clock",note:"конкретный момент в прошлом"},{word:"When…? / What time…?",note:"вопрос про момент в прошлом → did: When did you…?"},{word:"when I was a child",note:"законченный период жизни"},{word:"the other day",note:"на днях"},{word:"then, after that, first",note:"последовательность событий в рассказе"},{word:"this morning",note:"если утро уже прошло (сейчас день или вечер)"}],versus:[{tense:"present-perfect",ru:"Past simple — законченная история с названным временем (last year), к сегодняшнему дню она отношения не имеет. Present perfect — время не названо, а важно, что сейчас: паспорта нет.",a:{en:"I **lost** my passport in Spain last year.",ru:"В прошлом году в Испании у меня потерялся паспорт."},b:{en:"I'**ve lost** my passport! I can't fly tomorrow.",ru:"У меня пропал паспорт! Я не смогу завтра улететь."}},{tense:"past-continuous",ru:"Past simple — действие целиком, точкой: сначала звонок, потом Макс выключил телевизор. Past continuous — процесс, который уже шёл в момент звонка.",a:{en:"When Anna called, Max **turned off** the TV.",ru:"Когда Анна позвонила, Макс выключил телевизор."},b:{en:"When Anna called, Max **was watching** TV.",ru:"Когда Анна позвонила, Макс смотрел телевизор."}},{tense:"be-rule",ru:"Past simple — подлежащее само делает действие: кто-то украл. Was/were + V3 — пассив: с велосипедом это сделали; а was go или was went не бывает никогда.",a:{en:"Someone **stole** my bike last night.",ru:"Вчера вечером кто-то украл мой велосипед."},b:{en:"My bike **was stolen** last night.",ru:"Вчера вечером у меня украли велосипед."}}],mistakes:[{wrong:"Did you went to the party?",right:"Did you go to the party?",why:"После did глагол всегда в V1: прошлое уже показывает did, V2 не нужна."},{wrong:"I was go to the bank yesterday.",right:"I went to the bank yesterday.",why:"Was не ставится перед обычным глаголом: в утверждении прошлое показывает одно слово — went."},{wrong:"She didn't called me.",right:"She didn't call me.",why:"didn't + V1: проверь, что после didn't нет -ed и V2."},{wrong:"We have bought a new car last month.",right:"We bought a new car last month.",why:"Last month — законченное время: с ним только past simple, have не нужен."},{wrong:"Did you be at home yesterday?",right:"Were you at home yesterday?",why:"С be did не нужен: в вопросе was/were выходит вперёд — Were you…? Was it…?"},{wrong:"It was happened yesterday.",right:"It happened yesterday.",why:"Happen — обычный глагол, а не пассив: «это случилось» = it happened, без was."}],trick:"Правило «прошлое — только один раз»: в каждом сказуемом прошлое показывает одно слово. В утверждении это сам глагол (I went), в вопросе и отрицании — did, и тогда глагол возвращается в V1 (Did you go? I didn't go). Was/were тоже уже прошлое, поэтому ни was go, ни was went не бывает: после was/were идёт прилагательное, существительное, место, -ing или V3 (I was tired, it was made in Italy).",examples:[{en:"I **started** my new job last Monday.",ru:"В прошлый понедельник у меня был первый день на новой работе."},{en:"Last summer we **flew** to Istanbul and **stayed** with friends for a week.",ru:"Прошлым летом мы слетали в Стамбул и неделю жили у друзей."},{en:"**Did** you **sleep** well?",ru:"Хорошо спалось?"},{en:"She **didn't come** to the meeting because she **was** ill.",ru:"Она не пришла на встречу, потому что болела."},{en:"The flight **was** long, but the kids **were** fine.",ru:"Перелёт был долгим, но дети перенесли его нормально."},{en:"Where **did** you **buy** that jacket?",ru:"Откуда у тебя эта куртка?"},{en:"My laptop **crashed** an hour ago, and I **lost** all my changes.",ru:"Час назад у меня завис ноутбук, и все изменения пропали."},{en:"We **didn't have** time for breakfast, so we **bought** sandwiches at the station.",ru:"Мы не успели позавтракать, поэтому купили сэндвичи на вокзале."},{en:"When **did** your parents **get** married?",ru:"Когда поженились твои родители?"},{en:"He **wasn't** at work yesterday. **Was** he ill?",ru:"Вчера его не было на работе. Он болел?"}],exercises:[{id:"ps-did-get",type:"choice",prompt:"Did you ___ the email I sent this morning?",options:["got","getting","get","gets"],answer:2,rule:"Did + V1: Did you get…? (not got)",explain:"Did already shows the past, so the verb goes back to V1: get, not got.",ruHint:"После did — V1: Did you get…?"},{id:"ps-went-italy",type:"fill",before:"We ",after:" to Italy last summer and loved every minute.",answers:["went"],base:"go",rule:"Finished time → V2: go → went",explain:"Last summer is a finished time, so use past simple. Go is irregular: went.",ruHint:"Last summer — past simple: go → went."},{id:"ps-were-home",type:"choice",prompt:"___ you at home last night? I called you twice.",options:["Did","Was","Have","Were"],answer:3,rule:"be in the past: Were you…? (no did)",explain:"With be you don't need did: the question starts with was or were. With you, use were.",ruHint:"С be did не нужен: Were you at home?"},{id:"ps-accident-happened",type:"choice",prompt:"The accident ___ at about ten last night.",options:["was happened","happened","has happened","was happen"],answer:1,rule:"happen is not passive: it happened (no was)",explain:"Nobody 'happened' the accident: it just happened. So no was: happened. Has happened can't go with last night.",ruHint:"«Это случилось» — happened, без was."},{id:"ps-didnt-call",type:"errorTap",sentence:"She didn't called me back yesterday, so I emailed her.",wrong:2,correct:"She didn't call me back yesterday, so I emailed her.",rule:"didn't + V1 (not V2 or -ed)",explain:"Didn't already shows the past, so the verb stays in V1: didn't call.",ruHint:"После didn't — V1: didn't call."},{id:"ps-didnt-see",type:"fill",before:"Sorry, I ",after:" your message last night. My phone was off.",answers:["didn't see"],base:"not / see",rule:"Past negative: didn't + V1",explain:"Last night is a finished time, so use past simple. Negative: didn't + V1: didn't see (not didn't saw).",ruHint:"Отрицание в прошлом — didn't + V1: didn't see."},{id:"ps-when-start",type:"reorder",words:["when","did","you","start","learning","English"],end:"?",rule:"Past When…? → did + subject + V1",explain:"When asks about a finished moment, so use past simple: When did you start…? (not When have you started).",ruHint:"Вопрос с when о прошлом — с did, а не с have: When did you start…?"},{id:"ps-lived-omsk",type:"choice",prompt:"I ___ in Omsk for three years, and then I moved to Kazan.",options:["lived","have lived","have been living","live"],answer:0,rule:"Finished period → past simple, even with for",explain:"You don't live in Omsk now: that period is over, so use past simple. Present perfect with for means the situation still goes on.",ruHint:"Период закончился — past simple, даже с for: I lived."}]},{id:"past-continuous",group:"past",name:"Past Continuous",ruName:"Прошедшее длительное",short:"An action in progress at a moment in the past",idea:"Поставь прошлое на паузу и посмотри на стоп-кадр: что в этот момент было в процессе, то есть уже началось, но ещё не закончилось? Это и есть was/were + -ing. Чаще всего это фон истории: «мы ужинали» (длинное действие, continuous), «и тут зазвонил телефон» (короткое, past simple).",category:"tense-choice",forms:[{label:"+",parts:["I / he / she / it","was","V-ing"],example:"She **was cooking** dinner."},{label:"+ you/we/they",parts:["you / we / they","were","V-ing"],example:"We **were watching** a film."},{label:"−",parts:["subject","wasn't / weren't","V-ing"],example:"They **weren't listening**."},{label:"?",parts:["Was / Were","subject","V-ing?"],example:"**Were** you **sleeping**?"},{label:"Wh-?",parts:["What / Where…","was / were","subject","V-ing?"],example:"What **were** you **doing** at 9?"}],timeline:{marks:[{kind:"span",at:-.75,to:-.2,label:"I was cooking"},{kind:"point",at:-.45,label:"the phone rang"}],caption:"A long action was in progress when a short one happened."},uses:[{en:"In progress at a past moment",ru:"Действие было в процессе в конкретный момент прошлого: в 8 вечера, в момент звонка. Оно началось раньше и продолжалось после.",example:{en:"At 8 pm yesterday we **were driving** home.",ru:"Вчера в восемь вечера мы ехали домой."}},{en:"Interrupted by a short action",ru:"Длинное действие (was/were + -ing) прерывается коротким (past simple). Обычно их связывает when: долгое в continuous, короткое в simple.",example:{en:"She **was cooking** dinner when the phone rang.",ru:"Она готовила ужин, когда зазвонил телефон."}},{en:"Two actions at once",ru:"Два процесса шли одновременно, часто с while. Если важно, что оба шли как процесс, оба ставим в continuous.",example:{en:"While the kids **were sleeping**, we **were packing** for the trip.",ru:"Пока дети спали, мы собирали вещи в поездку."}},{en:"Background of a story",ru:"Описываем обстановку: что происходило вокруг, когда началась история. Сами события идут в past simple.",example:{en:"It **was raining**, and people **were hurrying** home. Suddenly the lights went out.",ru:"Шёл дождь, люди спешили домой. Вдруг погас свет."}},{en:"Polite requests",ru:"I was wondering if… — очень вежливая просьба. Прошедшее время тут не про прошлое, а про мягкость тона.",example:{en:"I **was wondering** if you could help me with the presentation.",ru:"Не могли бы вы помочь мне с презентацией?"}}],signals:[{word:"when",note:"чаще стоит перед коротким действием: …when the phone rang"},{word:"while",note:"чаще стоит перед длинным действием: while I was cooking"},{word:"as",note:"= while, действия идут одновременно: As we were leaving, …"},{word:"just as",note:"«как раз в тот момент, когда»"},{word:"at that moment"},{word:"at 8 pm yesterday",note:"конкретный момент в прошлом"},{word:"this time yesterday / last week",note:"«в это же время вчера / на прошлой неделе»"},{word:"all day / all evening",note:"подчёркивает процесс; past simple здесь тоже правильный"}],versus:[{tense:"past-simple",ru:"Were having: ужин уже шёл, когда она пришла. Had: сначала она пришла, а потом мы сели ужинать.",a:{en:"When Kate arrived, we **were having** dinner.",ru:"Когда Кейт пришла, мы ужинали."},b:{en:"When Kate arrived, we **had** dinner.",ru:"Когда Кейт пришла, мы сели ужинать."}},{tense:"past-perfect",ru:"Was leaving: она как раз уходила, и мы столкнулись в дверях. Had left: к нашему приходу её уже не было.",a:{en:"When we got to the office, Kate **was leaving**.",ru:"Когда мы пришли в офис, Кейт как раз уходила."},b:{en:"When we got to the office, Kate **had left**.",ru:"Когда мы пришли в офис, Кейт уже ушла."}},{tense:"used-to",ru:"По-русски в обоих случаях «бегала», но was jogging — процесс в конкретный момент (вчера в 7 утра). Регулярную привычку в прошлом передают used to или past simple, а не continuous.",a:{en:"At 7 am yesterday Anna **was jogging** in the park, so she missed your call.",ru:"Вчера в 7 утра Анна бегала в парке, поэтому пропустила твой звонок."},b:{en:"Anna **used to jog** in the park at 7 am every day.",ru:"Раньше Анна каждый день бегала в парке в 7 утра."}}],mistakes:[{wrong:"Last weekend we were drove to the sea.",right:"Last weekend we drove to the sea.",why:"Одно законченное действие — past simple без was: перед глаголом was ставят только для процесса (was + -ing) или пассива (was + V3)."},{wrong:"I was walk home when I saw the accident.",right:"I was walking home when I saw the accident.",why:"После was/were для процесса нужна форма на -ing: проверь окончание (was walking)."},{wrong:"Max was driving to work when his car was breaking down.",right:"Max was driving to work when his car broke down.",why:"Короткое действие, которое прервало процесс, ставится в past simple: broke down."},{wrong:"I was knowing the answer, but I didn't say it.",right:"I knew the answer, but I didn't say it.",why:"Know, believe, understand, own — глаголы состояния, в continuous их обычно не ставят, даже если по-русски «знать» звучит как процесс."},{wrong:"During I was waiting for the bus, I read the news.",right:"While I was waiting for the bus, I read the news.",why:"During ставят перед существительным (during the meeting), а перед «подлежащее + глагол» нужен while."},{wrong:"It was rained all morning, so we stayed at home.",right:"It was raining all morning, so we stayed at home.",why:"Was + V3 — это пассив; для процесса нужен was + -ing: was raining (или просто it rained)."}],trick:"Тест стоп-кадра: останови прошлое в нужный момент. Если на кадре действие идёт (уже началось и ещё не закончилось), ставь was/were + -ing, а если оно просто случилось — past simple без was. Проверка для was: если после него идёт глагол, то только в форме -ing (процесс) или V3 (пассив: was built), поэтому «was went» не бывает.",examples:[{en:"We **were driving** to the airport when we realised we'd forgotten the passports.",ru:"Мы ехали в аэропорт и тут поняли, что забыли паспорта."},{en:"What **were** you **doing** at 10 last night? Nobody answered the phone.",ru:"Что вы делали вчера в десять вечера? Никто не брал трубку."},{en:"While Max **was presenting** the project, his laptop suddenly died.",ru:"Пока Макс презентовал проект, у него внезапно сел ноутбук."},{en:"It **was snowing** heavily when we landed in Helsinki.",ru:"Когда мы приземлились в Хельсинки, шёл сильный снег."},{en:"They **weren't paying** attention while the manager **was explaining** the new rules.",ru:"Они не слушали, пока менеджер объяснял новые правила."},{en:"**Was** she **working** at the bank when you met her?",ru:"Она работала в банке, когда вы познакомились?"},{en:"This time last year we **were travelling** around Georgia.",ru:"В это же время в прошлом году мы путешествовали по Грузии."},{en:"Just as we **were leaving** the office, the boss called us back.",ru:"Мы уже выходили из офиса, когда начальник позвал нас обратно."},{en:"Anna's phone **was charging** in the other room, so she didn't see your message.",ru:"Телефон Анны заряжался в другой комнате, поэтому она не увидела твоё сообщение."},{en:"Who **was** Kate **talking** to at the party?",ru:"С кем Кейт разговаривала на вечеринке?"}],exercises:[{id:"pc-went-gym",type:"choice",prompt:"Yesterday I ___ to the gym after work.",options:["was went","went","was go","were going"],answer:1,rule:"One finished action → past simple, no was",explain:"This is one complete action, so use past simple: went. Before a verb, was needs -ing or V3, so was went is never correct.",ruHint:"Одно законченное действие — went, без was."},{id:"pc-watching-film",type:"choice",prompt:"When you called at 9, we ___ a film, so I didn't hear the phone.",options:["watched","was watching","were watching","have watched"],answer:2,rule:"In progress at a past moment → was/were + -ing",explain:"The film was already in progress when you called, so use past continuous. We takes were, not was.",ruHint:"Фильм уже шёл в момент звонка — процесс: were watching."},{id:"pc-doorbell-rang",type:"choice",prompt:"I was having a shower when the doorbell ___.",options:["rang","was ringing","has rung","had rung"],answer:0,rule:"Short action that interrupts → past simple",explain:"The shower is the long action in progress. The doorbell is the short action that interrupted it, so use past simple: rang.",ruHint:"Короткое действие, которое прервало процесс, — past simple: rang."},{id:"pc-kids-playing",type:"fill",before:"The kids ",after:" in the garden when it started to rain.",answers:["were playing","had been playing"],base:"play",rule:"Long action interrupted → was/were + -ing",explain:"The kids were already playing when the rain started. Kids is plural, so use were: were playing.",ruHint:"Дети уже играли, когда пошёл дождь: were playing."},{id:"pc-was-listening",type:"errorTap",sentence:"Sorry, I didn't hear you because I was listen to music.",wrong:8,correct:"Sorry, I didn't hear you because I was listening to music.",rule:"Past continuous = was/were + -ing",explain:"An action in progress needs was + -ing. Listen must take -ing after was: was listening.",ruHint:"После was для процесса — форма на -ing."},{id:"pc-what-doing",type:"reorder",words:["what","were","you","doing","when","I","called"],end:"?",alt:[["when","I","called","what","were","you","doing"]],rule:"Question: what + was/were + subject + -ing",explain:"In past continuous questions, was or were goes before the subject: What were you doing…?",ruHint:"Were ставим перед you: What were you doing…?"},{id:"pc-knew-answer",type:"fill",before:"I ",after:" the answer, but I was too nervous to say it.",answers:["knew"],base:"know",rule:"State verbs (know, want, like) → no continuous",explain:"Know is a state, not an action, so it does not take -ing. Use past simple: knew.",ruHint:"Know — глагол состояния: knew, а не was knowing."},{id:"pc-mia-leaving",type:"choice",prompt:"When I got to the party, Mia ___, so we only had time to say hi.",options:["had just left","was just leaving","has just left","is just leaving"],answer:1,rule:"Leaving at that moment → was leaving, not had left",explain:"Mia was in the middle of leaving when I arrived, so we met at the door. Had just left would mean she was already gone.",ruHint:"Она как раз уходила — was leaving; had left значит, что её уже не было."}]},{id:"past-perfect",group:"past",name:"Past Perfect",ruName:"Прошедшее совершённое («предпрошедшее»)",short:"The earlier past: what had happened before another past moment",idea:"Это «прошлое в прошлом». Рассказываешь историю в past simple, и вдруг нужно отмотать назад, к тому, что случилось ещё раньше: это и есть had + V3. Нет опорного момента в прошлом (события или времени вроде by Monday) — past perfect обычно не нужен, хватит past simple.",category:"perfect",forms:[{label:"+",parts:["I / you / he / she / it / we / they","had","V3"],example:"The film **had started**."},{label:"−",parts:["subject","hadn't","V3"],example:"We **hadn't met** before."},{label:"?",parts:["Had","subject","V3?"],example:"**Had** you **seen** it before?"},{label:"'d + V3 = had",parts:["I'd / she'd / they'd","V3"],example:"She'**d** already **gone** home."},{label:"Passive",parts:["had been","V3"],example:"All the tickets **had been sold**."}],timeline:{marks:[{kind:"result",at:-.75,to:-.3,label:"the film had started"},{kind:"point",at:-.3,label:"we arrived"}],caption:"Past perfect looks back from a moment in the past, not from now."},uses:[{en:"The earlier of two pasts",ru:"Два события в прошлом, и нужно показать, что одно случилось раньше другого. Раньше — had + V3, позже — past simple.",example:{en:"When we got to the cinema, the film **had already started**.",ru:"Когда мы добрались до кинотеатра, фильм уже начался."}},{en:"Experience up to then",ru:"Опыт или длительность до момента в прошлом: never … before, for, since. Это как present perfect, только точка отсчёта не «сейчас», а «тогда».",example:{en:"She **had never flown** before her trip to Japan.",ru:"До поездки в Японию она ни разу не летала."}},{en:"The reason for a past situation",ru:"Объясняем, почему тогда было так: причина случилась раньше.",example:{en:"He couldn't log in because he **had forgotten** his password.",ru:"Он не мог войти, потому что забыл пароль."}},{en:"Reported speech",ru:"После said / told то, что случилось раньше, часто сдвигается в had + V3: «я отправила файл вчера» → she said she had sent the file the day before.",example:{en:"She said she **had sent** the file the day before.",ru:"Она сказала, что отправила файл накануне."}},{en:"Unreal past with if",ru:"Третий тип условных и I wish про прошлое: if + had + V3 — то, чего на самом деле не было.",example:{en:"If she **had checked** the address, she wouldn't have got lost.",ru:"Если бы она проверила адрес, она бы не заблудилась."}}],signals:[{word:"already",note:"между had и V3: had already left"},{word:"just",note:"«только что» перед другим моментом: had just left"},{word:"by the time",note:"by the time + past simple, а то, что успело случиться раньше, — had + V3"},{word:"by 2020 / by Monday",note:"к какому-то моменту в прошлом"},{word:"when",note:"проверь порядок: started (после) или had started (раньше)?"},{word:"never … before",note:"опыта не было до момента в прошлом: had never seen"},{word:"for / since",note:"длительность до момента в прошлом: had known her for years"},{word:"before",note:"порядок и так ясен — можно и past simple"},{word:"after",note:"after уже показывает порядок: had + V3 можно, но не обязательно"}],versus:[{tense:"past-simple",ru:"Had started: встреча началась без нас, мы опоздали. Started: сначала пришли мы, а потом она началась.",a:{en:"When we arrived, the meeting **had started**.",ru:"Когда мы пришли, встреча уже началась."},b:{en:"When we arrived, the meeting **started**.",ru:"Как только мы пришли, началась встреча."}},{tense:"present-perfect",ru:"Hasn't seen смотрит из «сейчас»: они не виделись до сих пор. Hadn't seen смотрит из момента в прошлом: не виделись до той встречи.",a:{en:"She **hadn't seen** Tom for years, so she didn't recognise him at first.",ru:"Она много лет не видела Тома, поэтому не сразу его узнала."},b:{en:"She **hasn't seen** Tom for years, so she might not recognise him.",ru:"Она много лет не видела Тома, так что может его и не узнать."}},{tense:"past-continuous",ru:"Had left: его уже не было, мы разминулись. Was leaving: он как раз уходил, и мы застали его в дверях.",a:{en:"When we got to Tom's place, he **had left**.",ru:"Когда мы пришли к Тому, он уже ушёл."},b:{en:"When we got to Tom's place, he **was leaving**.",ru:"Когда мы пришли к Тому, он как раз уходил."}}],mistakes:[{wrong:"When we got to the station, the train was already left.",right:"When we got to the station, the train had already left.",why:"Поезд ушёл сам и раньше нас: had + V3; was + V3 — это пассив («кто-то оставил поезд»)."},{wrong:"When we got there, she has already left.",right:"When we got there, she had already left.",why:"Точка отсчёта в прошлом (when we got there), поэтому had, а не has."},{wrong:"By the time the police came, the thieves escaped.",right:"By the time the police came, the thieves had escaped.",why:"By the time = «к тому моменту»: всё, что успело случиться до него, ставится в had + V3."},{wrong:"Last summer I had visited my grandparents.",right:"Last summer I visited my grandparents.",why:"Past perfect — не «более прошедшее» время: если второго, более позднего события в прошлом нет, нужен past simple."},{wrong:"Max couldn't come because he had broke his leg.",right:"Max couldn't come because he had broken his leg.",why:"После had нужна V3: broken, а не broke (V2) — проверь третью колонку таблицы неправильных глаголов."},{wrong:"If I would have known, I would have come.",right:"If I had known, I would have come.",why:"В части с if про нереальное прошлое ставят had + V3, а would остаётся только во второй части."}],trick:"В русском «предпрошедшего» нет, поэтому делай тест «двух прошлых»: найди опорный момент в прошлом (when we arrived, by the time, by Monday) и спроси, случилось ли это ещё раньше и отматываешь ли ты назад. Если да — had + V3, а если события идут по порядку, одно за другим, хватит past simple. Когда порядок и так ясен из before или after, past perfect можно не ставить.",examples:[{en:"By the time she finished the report, everyone **had gone** home.",ru:"Когда она закончила отчёт, все уже ушли домой."},{en:"Tom **had never been** to a job interview before, so he was nervous.",ru:"Том раньше ни разу не был на собеседовании, поэтому волновался."},{en:"We couldn't check in because someone **had cancelled** our booking.",ru:"Мы не смогли заселиться, потому что кто-то отменил нашу бронь."},{en:"**Had** you **met** Anna before the conference?",ru:"Вы были знакомы с Анной до конференции?"},{en:"They **hadn't seen** each other for ten years, so the meeting was very emotional.",ru:"Они не виделись десять лет, поэтому встреча была очень трогательной."},{en:"At first nobody recognised Max: he **had grown** a beard.",ru:"Сначала Макса никто не узнал: он отрастил бороду."},{en:"The deploy failed because nobody **had updated** the config.",ru:"Деплой упал, потому что никто не обновил конфиг."},{en:"By 2020 my parents **had moved** to the seaside.",ru:"К 2020 году мои родители уже переехали к морю."},{en:"When she opened her bag, she realised she **had left** her passport at home.",ru:"Открыв сумку, она поняла, что оставила паспорт дома."},{en:"After the guests **had left**, we finally sat down and relaxed.",ru:"Когда гости ушли, мы наконец сели и расслабились."}],exercises:[{id:"pf-train-left",type:"choice",prompt:"When we got to the platform, the train ___, so we waited for the next one.",options:["has already left","had already left","was already left","already leaves"],answer:1,rule:"Earlier of two past actions → had + V3",explain:"The train left before we got to the platform, so use past perfect: had left. Was left is passive and means someone left the train.",ruHint:"Поезд ушёл раньше, чем мы пришли: had already left."},{id:"pf-had-gone",type:"choice",prompt:"By the time I called, they ___ home.",options:["had gone","had went","have gone","had go"],answer:0,rule:"had + V3 (gone), not had + V2 (went)",explain:"Past perfect is had + V3. Go – went – gone: the third form is gone.",ruHint:"После had — V3: gone."},{id:"pf-never-flown",type:"fill",before:"Kate was nervous on the flight because she ",after:" before.",answers:["had never flown"],base:"never / fly",rule:"never … before a past moment → had never + V3",explain:"Her experience is counted up to a moment in the past (the flight), so use past perfect: had never flown.",ruHint:"Ни разу до того полёта — had never flown."},{id:"pf-fixed-bug",type:"fill",before:"By the time the manager replied, I ",after:" the bug myself.",answers:["had fixed","had already fixed"],base:"fix",rule:"by the time + past simple; earlier action: had + V3",explain:"The fix happened before the reply. By the time asks what was already done by then: had fixed.",ruHint:"К моменту ответа баг уже был исправлен — had fixed."},{id:"pf-everyone-left",type:"errorTap",sentence:"Everyone left by the time we arrived at the party.",wrong:1,correct:"Everyone had left by the time we arrived at the party.",rule:"by the time → had + V3 in the other part",explain:"By the time means everyone left before we arrived. The earlier action needs past perfect: had left.",ruHint:"By the time = «к тому моменту»: все ушли раньше — had left."},{id:"pf-abroad-before",type:"reorder",words:["had","you","ever","been","abroad","before","that","trip"],end:"?",alt:[["before","that","trip","had","you","ever","been","abroad"]],rule:"Question: Had + subject + V3?",explain:"In past perfect questions, had goes before the subject: Had you ever been…?",ruHint:"Had ставим перед подлежащим: Had you ever been…?"},{id:"pf-alarm-left",type:"choice",prompt:"As soon as the fire alarm went off, everyone ___ the building.",options:["had left","left","has left","leaves"],answer:1,rule:"Actions in order, one after another → past simple",explain:"First the alarm went off, then people left. When actions follow each other in order, use past simple. Had left would mean they left before the alarm.",ruHint:"Сначала тревога, потом все вышли — по порядку, значит past simple."},{id:"pf-booked-earlier",type:"fill",before:"If we ",after:" the tickets earlier, we would have paid less.",answers:["had booked"],base:"book",rule:"Unreal past: if + had + V3, would have + V3",explain:"This is about the past, and it did not happen. After if, use past perfect: had booked. Would goes only in the other part.",ruHint:"«Если бы мы забронировали раньше» — if we had booked, без would."}]},{id:"past-perfect-continuous",group:"past",name:"Past Perfect Continuous",ruName:"Прошедшее совершённое длительное",short:"How long something had been going on before a past moment",idea:"Это present perfect continuous, только «сейчас» перенесено в прошлое: действие шло какое-то время до определённого момента в прошлом, а может, и после него. Оно отвечает на вопросы «сколько уже длилось к тому моменту?» и «почему тогда всё было так?» (он был без сил, потому что всю ночь работал). В живой речи это время нечастое: если длительность и процесс не важны, хватает past perfect или past simple.",category:"perfect",forms:[{label:"+",parts:["I / you / he / she / it / we / they","had been","V-ing"],example:"She **had been waiting** for an hour."},{label:"−",parts:["subject","hadn't been","V-ing"],example:"They **hadn't been sleeping** well."},{label:"?",parts:["Had","subject","been","V-ing?"],example:"**Had** they **been arguing**?"},{label:"How long?",parts:["How long","had","subject","been","V-ing?"],example:"How long **had** he **been working** there?"},{label:"Short form",parts:["I'd / we'd / she'd","been","V-ing"],example:"We'**d been driving** for hours."}],timeline:{marks:[{kind:"span",at:-.8,to:-.3,label:"we'd been waiting"},{kind:"point",at:-.3,label:"Tom arrived"}],caption:"An activity went on for some time up to a past moment."},uses:[{en:"How long, up to then",ru:"Сколько времени действие уже шло к определённому моменту в прошлом: for an hour, since morning, how long. Оно могло продолжаться и дальше.",example:{en:"She **had been working** at the bank for ten years when it closed.",ru:"К моменту закрытия банка она проработала там десять лет."}},{en:"Cause of a past situation",ru:"Объясняем, почему тогда всё выглядело так: усталость, мокрая дорога, красные глаза. Процесс шёл до этого момента и оставил след.",example:{en:"He was exhausted because he **had been coding** all night.",ru:"Он был без сил, потому что всю ночь писал код."}},{en:"Reported speech",ru:"После said / told форма have been + -ing часто сдвигается в had been + -ing. Если это всё ещё правда, можно оставить have been.",example:{en:"She told me she **had been looking** for a new job.",ru:"Она сказала мне, что ищет новую работу."}}],signals:[{word:"for + period",note:"сколько уже длилось к моменту в прошлом: for two hours"},{word:"since + start point",note:"с какого момента шло: since morning"},{word:"how long",note:"How long had you been…? — сколько уже длилось к тому моменту"},{word:"all day / all night",note:"весь период до того момента"},{word:"when",note:"отмечает момент в прошлом, до которого шло действие"},{word:"before",note:"до какого события шло действие: before she moved"},{word:"by the time"}],versus:[{tense:"past-perfect",ru:"Had been painting: шёл процесс (мог и не закончить), остались следы — одежда в краске. Had painted: работа сделана, виден результат — кухня как новая.",a:{en:"He **had been painting** the kitchen, so his clothes were covered in paint.",ru:"Он красил кухню, поэтому вся одежда была в краске."},b:{en:"He **had painted** the kitchen, so it looked brand new.",ru:"Он покрасил кухню, и она выглядела как новая."}},{tense:"past-continuous",ru:"Was crying: она плакала прямо в тот момент, когда мы вошли. Had been crying: уже не плакала, но было видно, что плакала до этого.",a:{en:"When we came in, she **had been crying**.",ru:"Когда мы вошли, было видно, что она плакала."},b:{en:"When we came in, she **was crying**.",ru:"Когда мы вошли, она плакала."}},{tense:"present-perfect-continuous",ru:"Have been waiting: ждём до сих пор, отсчёт от «сейчас». Had been waiting: ожидание закончилось в прошлом, когда пришёл Том.",a:{en:"We **had been waiting** for an hour when Tom arrived.",ru:"Мы ждали уже час, когда пришёл Том."},b:{en:"We **have been waiting** for an hour, and Tom still isn't here.",ru:"Мы ждём уже час, а Тома всё нет."}}],mistakes:[{wrong:"I was waiting for two hours when she finally came.",right:"I had been waiting for two hours when she finally came.",why:"Если говоришь, сколько действие уже длилось к моменту в прошлом (for two hours … when), нужно had been + -ing."},{wrong:"We had been waited for the bus for an hour when it finally came.",right:"We had been waiting for the bus for an hour when it finally came.",why:"Had been + V3 — это пассив («нас ждали»); «мы ждали» — процесс, значит -ing: had been waiting."},{wrong:"She has been working there for six years when the company closed.",right:"She had been working there for six years when the company closed.",why:"Точка отсчёта в прошлом (when the company closed), поэтому had, а не has."},{wrong:"By lunch she had been writing five emails.",right:"By lunch she had written five emails.",why:"Есть количество (five emails) — это результат, поэтому нужен past perfect simple: had written."},{wrong:"They had been knowing each other for years before they got married.",right:"They had known each other for years before they got married.",why:"Know — глагол состояния, в continuous его не ставят даже с for: had known."}],trick:"Возьми present perfect continuous (I've been waiting) и перенеси «сейчас» в прошлое: have превращается в had, и получается I'd been waiting when she called. Спроси себя: «сколько уже шло к тому моменту?» или «почему тогда было так?» Если ответ про процесс, бери had been + -ing; если про результат, количество или глагол состояния (know, believe, own), хватит had + V3.",examples:[{en:"Kate **had been waiting** for 20 minutes when the doctor finally called her in.",ru:"Кейт ждала уже 20 минут, когда врач наконец её позвал."},{en:"The road was wet: it **had been raining** all night.",ru:"Дорога была мокрая: всю ночь шёл дождь."},{en:"How long **had** you **been learning** English before you got the job?",ru:"Сколько вы учили английский до того, как получили эту работу?"},{en:"They **hadn't been talking** for long when the connection dropped.",ru:"Они проговорили совсем недолго, и тут связь оборвалась."},{en:"Her eyes were red. **Had** she **been crying**?",ru:"У неё были красные глаза. Она что, плакала?"},{en:"The developers **had been fixing** bugs for weeks before the release.",ru:"Разработчики несколько недель исправляли баги перед релизом."},{en:"By the time Max found a flat, he **had been looking** for three months.",ru:"Когда Макс нашёл квартиру, он искал её уже три месяца."},{en:"She said she **had been feeling** unwell since Monday.",ru:"Она сказала, что плохо себя чувствует с понедельника."},{en:"The server **had been running** without problems for months before it crashed.",ru:"Сервер месяцами работал без сбоев, пока не упал."},{en:"Our legs hurt because we **had been walking** around Rome all day.",ru:"У нас болели ноги: мы весь день гуляли по Риму."}],exercises:[{id:"ppc-waiting-hour",type:"choice",prompt:"We ___ for an hour when the taxi finally arrived.",options:["have been waiting","had been waiting","had been waited","were waited"],answer:1,rule:"How long, up to a past moment → had been + -ing",explain:"The waiting went on for an hour up to a moment in the past (the taxi arrived), so use had been waiting. Had been waited would be passive.",ruHint:"Ждали час до момента в прошлом — had been waiting."},{id:"ppc-how-long",type:"reorder",words:["how","long","had","you","been","waiting"],end:"?",rule:"How long + had + subject + been + -ing?",explain:"In the question, had goes before the subject, then been + -ing: How long had you been waiting?",ruHint:"Had — перед подлежащим, потом been waiting."},{id:"ppc-reading-book",type:"fill",before:"Max ",after:" the book for a week, but he still hadn't finished it.",answers:["had been reading"],base:"read",rule:"Unfinished activity up to then → had been + -ing",explain:"He read for a week but did not finish, so this is about the activity, not the result: had been reading. Had read would mean he finished it.",ruHint:"Читал неделю, но не дочитал — процесс: had been reading."},{id:"ppc-still-now",type:"choice",prompt:"I'm exhausted. I ___ on this report since 8 am, and it's still not finished.",options:["had been working","was working","have been working"],answer:2,rule:"Still going on now → have been, not had been",explain:"The work started at 8 am and is still going on now, so use present perfect continuous: have been working. Had been is for a moment in the past.",ruHint:"Работа идёт до сих пор — have been working; had been — только про прошлое."},{id:"ppc-friends-waiting",type:"errorTap",sentence:"When I finally found the café, my friends have been waiting for 40 minutes.",wrong:8,correct:"When I finally found the café, my friends had been waiting for 40 minutes.",rule:"End point in the past → had been, not have been",explain:"The waiting went on up to a past moment (when I found the café), so use had been waiting, not have.",ruHint:"Точка отсчёта в прошлом — had been, а не have been."},{id:"ppc-ten-calls",type:"choice",prompt:"By lunchtime she ___ ten calls, so she took a break.",options:["had been making","had made","has made","was making"],answer:1,rule:"How many (a number done) → had + V3, not -ing",explain:"Ten calls is a result you can count, so use past perfect simple: had made. The continuous form says how long, not how many.",ruHint:"Есть количество (ten calls) — результат: had made."},{id:"ppc-anna-crying",type:"choice",prompt:"Anna was smiling when we came in, but her eyes were red: she ___.",options:["had been crying","was crying","has been crying","had been cried"],answer:0,rule:"Traces of an earlier activity → had been + -ing",explain:"She was not crying any more, but her red eyes showed the earlier activity: had been crying. Was crying would mean she was crying at that moment.",ruHint:"Уже не плакала, но следы остались — had been crying."},{id:"ppc-known-years",type:"fill",before:"By 2015 they ",after:" each other for ten years.",answers:["had known"],base:"know",rule:"State verbs (know) → had + V3, not had been + -ing",explain:"Know is a state verb, so it does not take -ing, even with for. Use past perfect simple: had known.",ruHint:"Know — глагол состояния: had known, а не had been knowing."}]},{id:"future-simple",group:"future",name:"Future Simple (will)",ruName:"Будущее простое: will",short:"will + V1: decisions made now, promises, offers, opinions and facts about the future",idea:"Will — это будущее, которое рождается прямо в момент разговора: ты решаешь, обещаешь, предлагаешь помощь или говоришь, как, по-твоему, всё будет. Ещё will — спокойный факт о будущем: «в мае мне исполнится 30». А если план появился раньше разговора, will обычно не нужен: там going to или present continuous.",category:"tense-choice",forms:[{label:"+",parts:["I / you / he / she / it / we / they","will ('ll)","V1"],example:"I'**ll text** you the address tonight."},{label:"−",parts:["subject","won't (will not)","V1"],example:"She **won't like** this idea."},{label:"?",parts:["Will","subject","V1?"],example:"**Will** you **help** me with the slides?"},{label:"Shall I / we?",parts:["Shall","I / we","V1?"],example:"**Shall** we **order** a pizza?"}],timeline:{marks:[{kind:"point",at:0,label:"I decide now"},{kind:"point",at:.45,label:"I'll call you back"}],caption:"Decided, promised or predicted now; the action comes later."},uses:[{en:"Decision on the spot",ru:"Решаешь прямо в момент речи, в ответ на ситуацию: звонит телефон, кончилось молоко, понравилась вещь в магазине.",example:{en:"You don't have cash? Don't worry, I'**ll pay**.",ru:"Нет наличных? Не волнуйся, я заплачу."}},{en:"Promises and refusals",ru:"Обещаешь (I'll…) или отказываешься (I won't…). О вещах won't значит «не хочет работать»: The laptop won't turn on — ноутбук не включается.",example:{en:"I'**ll send** you the contract tonight, I promise.",ru:"Пришлю тебе договор сегодня вечером, обещаю."}},{en:"Offers and requests",ru:"Предложить помощь — I'll… или Shall I…? («давай я…?»; в американском английском чаще Should I…?). Попросить — Will you…?, а мягче и вежливее — Could you…?",example:{en:"**Shall** I **book** a table for Friday?",ru:"Забронировать столик на пятницу?"}},{en:"Predictions: your opinion",ru:"Прогноз по твоему мнению, опыту или ощущению, часто с I think, I'm sure, probably. Если вывод следует из того, что видно прямо сейчас, обычно берут going to.",example:{en:"I think the meeting **will take** about an hour.",ru:"Думаю, встреча займёт около часа."}},{en:"Facts about the future",ru:"Нейтральный факт, который наступит сам собой, без чьего-то решения: возраст, даты, природа.",example:{en:"I'**ll be** 30 in May.",ru:"В мае мне исполнится 30."}}],signals:[{word:"I think / I don't think",note:"отрицание обычно ставят в think: I don't think he'll come"},{word:"probably / definitely",note:"после will, но перед won't: He'll probably come. He probably won't come."},{word:"I'm sure / I bet"},{word:"I promise"},{word:"I hope",note:"после I hope можно и will, и present simple: I hope you (will) like it"},{word:"maybe / perhaps"},{word:"OK, I'll… / Right, I'll…",note:"решение прямо сейчас"},{word:"Shall I…? / Shall we…?",note:"предложить помощь или что-то сделать вместе"},{word:"tomorrow / next year",note:"слово-время форму не выбирает: если уже договорились, нужен present continuous (I'm meeting her tomorrow)"}],versus:[{tense:"going-to",ru:"Will — решение рождается прямо в разговоре. Going to — решение было раньше, ты просто сообщаешь о нём.",a:{en:"There's no coffee left? OK, I'**ll buy** some after work.",ru:"Кофе кончился? Ладно, куплю после работы."},b:{en:"I know there's no coffee left. I'**m going to buy** some after work.",ru:"Знаю, что кофе кончился. Как раз собираюсь купить после работы."}},{tense:"present-continuous",ru:"Present continuous — договорённость со временем и людьми, как запись в календаре. Will здесь звучит как догадка или решение на ходу.",a:{en:"I'**ll** probably **see** Tom on Saturday.",ru:"Наверное, увижусь с Томом в субботу."},b:{en:"I'**m seeing** Tom on Saturday. We've booked a table for two.",ru:"В субботу я встречаюсь с Томом. Мы забронировали столик на двоих."}},{tense:"time-clauses",ru:"После when, if, as soon as, before, until в значении «когда / если это случится» will не ставят, там present simple. Но если when — это вопрос «когда?», will нужен: I don't know when he'll call.",a:{en:"I don't know when Max **will call**.",ru:"Не знаю, когда Макс позвонит (вопрос «когда?»)."},b:{en:"I'll tell you when Max **calls**.",ru:"Я скажу тебе, когда Макс позвонит (время: в тот момент)."}}],mistakes:[{wrong:"It's perfect. OK, I take it.",right:"It's perfect. OK, I'll take it.",why:"«Беру» по-русски звучит в настоящем, но решение в момент речи в английском — это will: I'll take it."},{wrong:"I'll pay you back when I will get my salary.",right:"I'll pay you back when I get my salary.",why:"После when, if, as soon as о будущем ставь present simple, а will оставляй только в главной части."},{wrong:"I will meet Anna tonight. We've already booked a table.",right:"I'm meeting Anna tonight. We've already booked a table.",why:"Есть договорённость (столик забронирован), значит, present continuous; will звучит так, будто решение пришло только что."},{wrong:"Will I open the window?",right:"Shall I open the window?",why:"Предлагая «давай я…?», говори Shall I…? (или Should I…?), а Will I…? спрашивает о будущем факте, например Will I need a visa?"},{wrong:"I will can help you tomorrow.",right:"I'll be able to help you tomorrow.",why:"Два модальных глагола подряд не ставят: «смогу» = will be able to, а если завтра у тебя просто есть время, хватит I can help you tomorrow."},{wrong:"Tomorrow will be rain.",right:"It will rain tomorrow.",why:"Это калька с «завтра будет дождь»: нужно подлежащее it (It will rain) или оборот There will be rain."}],trick:"Спроси себя: когда появилось это решение? Родилось прямо сейчас, пока ты говоришь, — will («OK, I'll take it»). Было до разговора — going to, а если уже есть договорённость со временем и людьми — present continuous.",examples:[{en:"I'm in a meeting. I'**ll call** you back in ten minutes.",ru:"Я на встрече. Перезвоню через десять минут."},{en:"Don't worry, I **won't tell** anyone about it.",ru:"Не волнуйся, я никому об этом не скажу."},{en:"**Will** you **be** in the office tomorrow?",ru:"Ты завтра будешь в офисе?"},{en:"I think the update **will fix** the login bug.",ru:"Думаю, обновление исправит баг со входом."},{en:"**Shall** I **book** a taxi to the airport for you?",ru:"Заказать тебе такси в аэропорт?"},{en:"Prices **will** probably **go** up again next year.",ru:"Цены, наверное, снова вырастут в следующем году."},{en:"I don't think they'**ll finish** the project on time.",ru:"Не думаю, что они закончат проект вовремя."},{en:"This jacket is great. I'**ll take** it.",ru:"Отличная куртка. Беру."},{en:"The laptop **won't turn on**. Can you take a look?",ru:"Ноутбук не включается. Посмотришь?"},{en:"**Will** you **help** me move on Saturday?",ru:"Поможешь мне с переездом в субботу?"}],exercises:[{id:"fs-phone-get",type:"choice",prompt:"The phone's ringing. Stay there, I ___ it.",options:["get","will get","am going to get","getting"],answer:1,rule:"Decision at the moment of speaking → will",explain:"You decide right now, as the phone rings, so use will: I'll get it. Going to is for decisions made before.",ruHint:"Решение прямо сейчас — I'll get it («я отвечу»)."},{id:"fs-milk-buy",type:"fill",before:"We're out of milk? No problem, I ",after:" some on my way home.",answers:["will buy","'ll buy","can buy","could buy"],base:"buy",rule:"Instant decision → will + V1",explain:"You hear about the milk now and decide now, so use will + V1: I'll buy. No to and no -s after will.",ruHint:"«Куплю» — решение на ходу: I'll buy."},{id:"fs-promise-late",type:"fill",before:"I'm so sorry. I promise I ",after:" be late again.",answers:["won't","will never","'ll never","won't ever","am not going to","'m not going to"],base:"will + not",rule:"Promise → will / won't + V1",explain:"A promise about the future uses will. The negative is won't (will not) + V1: I won't be late. In speech, I'm not going to be late is also fine.",ruHint:"Обещание — will; «не опоздаю» = I won't be late."},{id:"fs-shall-window",type:"choice",prompt:"It's really hot in here. ___ I open the window?",options:["Am","Will","Shall","Have"],answer:2,rule:"Offer → Shall I…? (= Do you want me to…?)",explain:"To offer help, ask Shall I…? (Americans often say Should I…?). Will I…? asks about the future, it doesn't offer anything.",ruHint:"«Открыть окно?» — это предложение: Shall I…?"},{id:"fs-flour-cake",type:"choice",prompt:"I've bought flour and eggs because I ___ a cake for Max's birthday.",options:["am going to bake","will bake","bake","would bake"],answer:0,rule:"Decided before → going to, not will",explain:"The decision came before buying the flour, so it's a plan: I'm going to bake. Will is for decisions made at the moment of speaking.",ruHint:"Решение было раньше (продукты уже куплены) — going to."},{id:"fs-as-soon-as",type:"errorTap",sentence:"I'll send you the report as soon as I will finish it.",wrong:9,correct:"I'll send you the report as soon as I finish it.",rule:"when / if / as soon as + present simple, not will",explain:"After when, if, as soon as and before, English uses present simple for the future: as soon as I finish. Will stays in the main part.",ruHint:"После as soon as — present simple: as soon as I finish."},{id:"fs-able-to",type:"fill",before:"Don't worry, in a few months you'll ",after:" watch films without subtitles.",answers:["be able to"],base:"can",rule:"Future ability → will be able to (never will can)",explain:"Two modals can't go together, so you'll can is wrong. For an ability you will have in the future, use will be able to: you'll be able to watch.",ruHint:"«Сможешь» = will be able to; will can не бывает."},{id:"fs-dont-think",type:"reorder",words:["I","don't","think","they","will","like","it"],alt:[["they","don't","think","I","will","like","it"]],rule:"I don't think + will: the 'not' goes with think",explain:"English usually makes think negative and keeps will positive: I don't think they will like it.",ruHint:"«Не думаю, что им понравится» — I don't think they will…"}]},{id:"going-to",group:"future",name:"Be Going To",ruName:"Собираюсь: be going to",short:"Plans decided before now, and predictions from what you can see now",idea:"Going to — это будущее, у которого уже есть корни в настоящем: решение принято до разговора или признаки видны прямо сейчас. «Я собираюсь сменить работу» — план уже в голове; «смотри, сейчас упадёт» — всё к этому идёт. А was going to — план или ожидание в прошлом; чаще всего так говорят о том, что не сбылось.",category:"tense-choice",forms:[{label:"+",parts:["subject","am / is / are","going to","V1"],example:"We'**re going to rent** a bigger flat."},{label:"−",parts:["subject","am not / isn't / aren't","going to","V1"],example:"I'**m not going to work** this weekend."},{label:"?",parts:["Am / Is / Are","subject","going to","V1?"],example:"**Are** you **going to apply** for that job?"},{label:"Past plan",parts:["subject","was / were","going to","V1"],example:"They **were going to sell** the car, but they changed their minds."},{label:"Speech",parts:["subject","am / is / are","gonna","V1"],example:"I'**m gonna grab** a coffee."}],timeline:{marks:[{kind:"result",at:-.6,to:0,label:"decided earlier"},{kind:"point",at:.5,label:"we're going to move"}],caption:"The decision or the signs are here now; the action comes later."},uses:[{en:"Plans decided earlier",ru:"Решение принято до разговора, это твоё намерение. Время и детали при этом ещё могут быть не согласованы.",example:{en:"I'**m going to look** for a new job this year.",ru:"В этом году я собираюсь искать новую работу."}},{en:"Prediction from evidence",ru:"Видишь признаки прямо сейчас и делаешь вывод: всё к этому идёт.",example:{en:"She's so pale. I think she'**s going to faint**.",ru:"Она такая бледная. Кажется, сейчас упадёт в обморок."}},{en:"Asking about plans",ru:"Are you going to…? — спросить о намерениях: что человек уже решил сделать.",example:{en:"What **are** you **going to do** after the course?",ru:"Что ты собираешься делать после курса?"}},{en:"Plans that didn't happen",ru:"Was / were going to — план или ожидание в прошлом; чаще всего то, что не сбылось. По-русски «собирались, но…».",example:{en:"We **were going to have** a picnic, but it started to rain.",ru:"Мы собирались устроить пикник, но пошёл дождь."}}],signals:[{word:"Look! / Look at…",note:"признаки видны прямо сейчас"},{word:"Watch out! / Careful!",note:"вот-вот случится: You're going to fall!"},{word:"I've decided / We've decided",note:"решение уже принято"},{word:"this year / next summer",note:"время само форму не выбирает: важно, решено ли заранее"},{word:"What are you going to…?",note:"вопрос о планах"},{word:"was going to … but",note:"план был, но не сбылся"},{word:"gonna",note:"разговорное going to + глагол; am / is / are всё равно нужен, в официальном письме не пиши"}],versus:[{tense:"future-simple",ru:"Going to — решение принято заранее (продукты уже куплены), will — решаешь прямо сейчас. С прогнозами похоже: going to — по признакам, которые видны сейчас, will — по твоему мнению.",a:{en:"We'**re going to bake** a cake for the guests. We bought everything yesterday.",ru:"Мы собираемся испечь торт для гостей. Вчера всё купили."},b:{en:"No dessert for the guests? OK, I'**ll bake** a cake.",ru:"Для гостей нет десерта? Ладно, испеку торт."}},{tense:"present-continuous",ru:"Going to — намерение: решение есть, но записи может ещё не быть. Present continuous — договорённость с конкретным временем, как запись в календаре; если всё уже организовано, часто подходят оба.",a:{en:"I'**m going to see** a doctor about my back.",ru:"Собираюсь сходить к врачу: спина болит."},b:{en:"I'**m seeing** the doctor at ten tomorrow.",ru:"Завтра в десять у меня приём у врача."}}],mistakes:[{wrong:"She going to quit her job.",right:"She's going to quit her job.",why:"Going to не работает без am / is / are: проверь, что перед going to стоит be (с gonna то же самое: I'm gonna)."},{wrong:"Your bag looks heavy. I'm going to help you.",right:"Your bag looks heavy. I'll help you.",why:"Помощь, которую предлагаешь прямо сейчас, — это will; going to звучит так, будто план был заранее."},{wrong:"We'll buy a new sofa on Saturday. We've already chosen one.",right:"We're going to buy a new sofa on Saturday. We've already chosen one.",why:"Решение принято заранее (диван уже выбран), значит, going to или present continuous, а не will."},{wrong:"This summer I learn to drive.",right:"This summer I'm going to learn to drive.",why:"Present simple о будущем — для расписаний (поезда, сеансы) и после when / if, а личный план — going to."},{wrong:"Is going to rain.",right:"It's going to rain.",why:"В английском нужно подлежащее: «будет дождь» = it's going to rain."},{wrong:"I was going to called you, but I forgot.",right:"I was going to call you, but I forgot.",why:"После going to всегда V1, даже в прошедшем: прошлое показывает was, а не сам глагол."}],trick:"Going to = «к этому всё идёт»: у будущего уже есть опора в настоящем — твоё решение или видимые признаки. Если опоры нет и решаешь на ходу — will. Проверка: можно добавить «уже решено» или «смотри, вот признаки»? Значит, going to.",examples:[{en:"I'**m going to ask** my boss for a raise next week.",ru:"На следующей неделе собираюсь попросить у начальника прибавку."},{en:"We'**re not going to buy** a new car this year.",ru:"В этом году мы не собираемся покупать новую машину."},{en:"**Are** you **going to watch** the match tonight?",ru:"Будешь смотреть матч сегодня вечером?"},{en:"Look at this traffic! We'**re going to miss** our flight.",ru:"Посмотри, какие пробки! Мы опоздаем на рейс."},{en:"She'**s going to have** a baby in October.",ru:"В октябре у неё будет ребёнок."},{en:"Tom **was going to come**, but he had to work late.",ru:"Том собирался прийти, но ему пришлось задержаться на работе."},{en:"How **are** you **going to explain** this to the client?",ru:"Как ты собираешься объяснять это клиенту?"},{en:"The server is overloaded. The site **is going to crash**.",ru:"Сервер перегружен. Сайт вот-вот упадёт."},{en:"My parents **are going to visit** us at Christmas.",ru:"Родители собираются приехать к нам на Рождество."},{en:"He **isn't going to like** this news.",ru:"Ему эта новость не понравится."}],exercises:[{id:"gt-clouds-rain",type:"choice",prompt:"Look at those black clouds! It ___ rain.",options:["is going to","goes to","is going","going to"],answer:0,rule:"Evidence you see now → am / is / are going to",explain:"You can see the clouds now, so it's a prediction from evidence: is going to + V1. You need both is and to.",ruHint:"Признаки видны сейчас — it's going to rain."},{id:"gt-box-help",type:"choice",prompt:"That box looks heavy. Wait, I ___ you!",options:["am going to help","will help","help","am helping"],answer:1,rule:"Decision right now → will, not going to",explain:"You decide to help at this moment, so use will: I'll help you. Going to is for plans made before.",ruHint:"Решение в момент речи — will: I'll help you."},{id:"gt-parents-car",type:"fill",before:"My parents ",after:" a new car next month. They've already chosen the model.",answers:["are going to buy","are buying","are planning to buy","will be buying"],base:"buy",rule:"Decided plan → am / is / are going to + V1",explain:"They decided before now, so use are going to buy, and don't forget are. Are buying and are planning to buy also work for a fixed plan.",ruHint:"План уже решён — are going to buy (не забудь are)."},{id:"gt-summer-visit",type:"choice",prompt:"Any plans for the summer? — Yes, we've already decided: we ___ my grandparents in Tver.",options:["will visit","visit","are going to visit","visited"],answer:2,rule:"Plan made before → going to, not will",explain:"The decision was made before the question, so use are going to visit. Will would sound like you decide right now.",ruHint:"Уже решено заранее — going to."},{id:"gt-was-going-call",type:"fill",before:"Sorry! I was ",after:" you last night, but I fell asleep.",answers:["going to call","planning to call","supposed to call","meant to call","intending to call","about to call"],base:"call",rule:"Plan that didn't happen → was going to + V1",explain:"There was a plan to call, but it didn't happen. After was, add going to + V1: I was going to call. Was planning to / supposed to call also work.",ruHint:"План в прошлом, который не сбылся, — was going to call."},{id:"gt-apply-v1",type:"errorTap",sentence:"Are you going to applying for the team lead job?",wrong:4,correct:"Are you going to apply for the team lead job?",rule:"going to + V1, not -ing",explain:"After going to, use the base verb: going to apply. The -ing is already in going.",ruHint:"После going to — V1: going to apply."},{id:"gt-rome-flight",type:"choice",prompt:"We ___ to Rome in May, but the airline cancelled our flight.",options:["are going to fly","will fly","went to fly","were going to fly"],answer:3,rule:"Past plan that failed → was / were going to",explain:"The plan was in the past and it didn't happen (the flight was cancelled), so use were going to fly.",ruHint:"«Собирались, но не вышло» — were going to."},{id:"gt-weekend-what",type:"reorder",words:["what","are","you","going","to","do","this","weekend"],end:"?",alt:[["this","weekend","what","are","you","going","to","do"]],rule:"wh- + am / is / are + subject + going to + V1",explain:"In a question, are goes before you: What are you going to do? Don't drop are.",ruHint:"«Что собираешься делать на выходных?» — What are you going to do…"}]},{id:"future-continuous",group:"future",name:"Future Continuous",ruName:"Будущее длительное",short:"will be + -ing: in the middle of an action at a moment in the future",idea:"Мысленно перенесись в момент в будущем и посмотри, что там происходит: действие уже идёт, ты в самой его середине. «Завтра в десять я буду лететь в Дубай» — это will be + -ing. Ещё так мягко спрашивают о чужих планах и говорят о том, что и так произойдёт по обычному ходу дел.",category:"tense-choice",forms:[{label:"+",parts:["subject","will be ('ll be)","V-ing"],example:"At noon I'**ll be giving** a talk."},{label:"−",parts:["subject","won't be","V-ing"],example:"We **won't be using** the meeting room today."},{label:"?",parts:["Will","subject","be","V-ing?"],example:"**Will** you **be working** late tonight?"}],timeline:{marks:[{kind:"span",at:.25,to:.8,label:"flying to Dubai"},{kind:"point",at:.5,label:"tomorrow at 10"}],caption:"At that future moment, the action is already in progress."},uses:[{en:"Mid-action at a future time",ru:"В конкретный момент будущего действие будет в процессе: началось раньше и ещё не закончилось.",example:{en:"This time next week we'**ll be skiing** in the mountains.",ru:"Через неделю в это время мы будем кататься на лыжах в горах."}},{en:"Polite questions about plans",ru:"Will you be + -ing? — нейтральный вопрос о планах, часто перед просьбой. Will you come? звучит как приглашение, а Will you be coming? — просто «ты планируешь прийти?».",example:{en:"**Will** you **be going** to the shops later? We need some bread.",ru:"Ты потом пойдёшь в магазин? Нам нужен хлеб."}},{en:"As a matter of course",ru:"То, что и так произойдёт по обычному ходу дел, а не по специальному решению: «я всё равно там буду», поэтому заодно могу помочь.",example:{en:"I'**ll be passing** the post office anyway, so I can send your parcel.",ru:"Я всё равно буду проходить мимо почты, могу отправить твою посылку."}},{en:"Guess about right now",ru:"Догадка о том, что человек, скорее всего, делает прямо сейчас: «наверняка он сейчас…».",example:{en:"Don't call Max now. He'**ll be driving** home.",ru:"Не звони Максу сейчас, он, наверное, едет домой."}}],signals:[{word:"this time tomorrow / next week",note:"главный сигнал: что будет идти в этот момент будущего"},{word:"at 10 tomorrow / at noon on Friday",note:"точный момент, когда действие уже идёт"},{word:"when you arrive / get there",note:"в части с when — present simple, в главной — will be + -ing: When you arrive, I'll be cooking."},{word:"all day tomorrow / all evening",note:"подчёркивает, что процесс займёт весь отрезок"},{word:"Will you be …-ing?",note:"вежливый вопрос о планах"},{word:"anyway",note:"«всё равно буду там»: само собой, без специального решения"},{word:"soon / shortly",note:"в объявлениях: We'll be landing shortly."}],versus:[{tense:"future-simple",ru:"Will be cooking — в момент её прихода готовка уже идёт. Will cook — сначала она приходит, потом я начинаю готовить.",a:{en:"When Anna arrives, I'**ll be cooking** dinner.",ru:"Когда Анна придёт, я буду готовить ужин (уже в процессе)."},b:{en:"When Anna arrives, I'**ll cook** dinner.",ru:"Когда Анна придёт, я приготовлю ужин (начну после её прихода)."}},{tense:"future-perfect",ru:"Will be writing — в шесть я ещё в процессе. Will have written — к шести работа уже готова, важен результат.",a:{en:"At six I'**ll be writing** the report.",ru:"В шесть я буду писать отчёт (ещё в процессе)."},b:{en:"By six I'**ll have written** the report.",ru:"К шести я уже напишу отчёт (будет готов)."}}],mistakes:[{wrong:"At eight tonight I'll watch the match, so don't call.",right:"At eight tonight I'll be watching the match, so don't call.",why:"«Буду смотреть» в конкретный момент — это процесс, значит, will be + -ing, а не просто will + V1."},{wrong:"This time next week I will flying to Dubai.",right:"This time next week I will be flying to Dubai.",why:"-ing без be не работает: проверь, что между will и -ing стоит be."},{wrong:"I will be call you tomorrow.",right:"I'll call you tomorrow.",why:"Will be + V1 не бывает: для обычного обещания хватит will + V1 (I'll call you), а будущий процесс — will be + -ing."},{wrong:"I will be knowing the results tomorrow.",right:"I will know the results tomorrow.",why:"Know — глагол состояния, в continuous его не ставят: I'll know."},{wrong:"When you will land, I'll be waiting in the car.",right:"When you land, I'll be waiting in the car.",why:"После when о будущем ставь present simple, а will be + -ing оставляй только в главной части."}],trick:"Представь стоп-кадр: завтра, 10:00, камера на паузе. Если в кадре ты посреди действия — will be + -ing. Если действие начнётся только в этот момент или после него — will + V1, а если к нему уже закончено — will have + V3.",examples:[{en:"This time tomorrow I'**ll be flying** to Dubai.",ru:"Завтра в это время я буду лететь в Дубай."},{en:"Don't call at nine. We'**ll be putting** the kids to bed.",ru:"Не звони в девять: мы будем укладывать детей спать."},{en:"**Will** you **be using** the meeting room after lunch?",ru:"Тебе нужна будет переговорка после обеда?"},{en:"I **won't be working** on Friday, so let's meet then.",ru:"В пятницу я не работаю, так что давай встретимся."},{en:"In ten years, robots **will be doing** most of this work.",ru:"Через десять лет большую часть этой работы будут делать роботы."},{en:"When you get to the station, I'**ll be waiting** at the main exit.",ru:"Когда приедешь на вокзал, я буду ждать у главного выхода."},{en:"She **won't be coming** to the party. She's working that night.",ru:"Она не придёт на вечеринку: в тот вечер она работает."},{en:"I'**ll be seeing** Anna at work tomorrow anyway, so I can give her the keys.",ru:"Я завтра всё равно увижу Анну на работе, так что могу передать ей ключи."},{en:"Ladies and gentlemen, we'**ll be landing** in Dubai in twenty minutes.",ru:"Дамы и господа, через двадцать минут мы совершим посадку в Дубае."},{en:"**Will** they **be joining** us for dinner tonight?",ru:"Они будут ужинать с нами сегодня?"}],exercises:[{id:"fc-beach-lying",type:"choice",prompt:"This time tomorrow I ___ on a beach in Antalya.",options:["will lie","will be lying","will lying","will be lie"],answer:1,rule:"this time tomorrow → will be + -ing",explain:"At that moment tomorrow the action will be in progress, so use will be + -ing: will be lying.",ruHint:"«Буду лежать» в момент будущего — will be lying."},{id:"fc-japan-travel",type:"fill",before:"This time next month we'll ",after:" around Japan!",answers:["be travelling","be traveling"],base:"travel",rule:"will + be + -ing for an action in progress",explain:"This time next month the trip will be in progress, so after will add be + -ing: be travelling (American spelling: traveling).",ruHint:"После will — be + -ing: be travelling."},{id:"fc-train-waiting",type:"choice",prompt:"When your train arrives, I ___ for you on the platform.",options:["will be waiting","will have waited","waited","will waiting"],answer:0,rule:"Already in progress at that moment → will be + -ing",explain:"The waiting starts before the train arrives, so at that moment it is in progress: I'll be waiting.",ruHint:"Ожидание уже идёт, когда поезд приходит, — will be waiting."},{id:"fc-be-sitting",type:"errorTap",sentence:"This time tomorrow I'll be sit on a plane to Dubai.",wrong:5,correct:"This time tomorrow I'll be sitting on a plane to Dubai.",rule:"will be + -ing, never will be + V1",explain:"After be, the verb needs -ing for an action in progress: I'll be sitting.",ruHint:"После be — -ing: be sitting."},{id:"fc-car-tonight",type:"choice",prompt:"___ you be using the car tonight? I need to go to IKEA.",options:["Do","Are","Will","Have"],answer:2,rule:"Polite question about plans: Will you be + -ing?",explain:"Will you be using…? politely asks about someone's plans before you ask for something. Only will goes with be + -ing here.",ruHint:"Вежливо узнать планы — Will you be using…?"},{id:"fc-know-results",type:"fill",before:"I ",after:" the results tomorrow, so I'll text you then.",answers:["will know","'ll know","should know"],base:"know",rule:"State verb know → no -ing: will know",explain:"Know is a state verb, so it doesn't take -ing, even in the future: I'll know, not I'll be knowing.",ruHint:"know — глагол состояния: I'll know, без be knowing."},{id:"fc-when-finish",type:"errorTap",sentence:"Call me when you will finish. I'll be having lunch nearby.",wrong:4,correct:"Call me when you finish. I'll be having lunch nearby.",rule:"After when → present simple, not will",explain:"In a time clause with when, English uses present simple for the future: when you finish.",ruHint:"После when — present simple: when you finish."},{id:"fc-flying-home",type:"reorder",words:["this","time","tomorrow","I","will","be","flying","home"],alt:[["I","will","be","flying","home","this","time","tomorrow"]],rule:"Time phrase + will be + -ing",explain:"Build the form step by step: will + be + flying. The time phrase can go at the start or at the end.",ruHint:"«Завтра в это время я буду лететь домой» — will be flying."}]},{id:"future-perfect",group:"future",name:"Future Perfect",ruName:"Будущее совершённое",short:"Done before a point in the future",idea:"Представь, что ты переносишься в будущее, скажем в пятницу вечером, и оглядываешься назад: отчёт к этому моменту уже готов. Это и есть future perfect: will have + V3, «к такому-то моменту уже будет сделано». Ему почти всегда нужна точка в будущем: by Friday, by then, by the time you come.",category:"perfect",forms:[{label:"+",parts:["I / you / he / she / it / we / they","will have","V3"],example:"She'**ll have left** by then."},{label:"−",parts:["subject","won't have","V3"],example:"I **won't have finished** by six."},{label:"?",parts:["Will","subject","have","V3?"],example:"**Will** you **have finished** by Friday?"},{label:"Short answer",parts:["Yes, I will.","No, I won't."],example:"**Will** they **have landed** by ten? Yes, they **will**."}],timeline:{marks:[{kind:"result",at:.2,to:.65,label:"I'll have finished"},{kind:"point",at:.65,label:"Friday"}],caption:"On Friday, the report is already done."},uses:[{en:"Done before a future point",ru:"Действие закончится до определённого момента в будущем, и в этот момент уже будет результат. Рядом почти всегда by + время: by Monday, by 2030, by then. Простое will с by тоже не ошибка (I'll send it by Monday), а will have подчёркивает «к тому моменту уже будет готово».",example:{en:"I'**ll have sent** you the contract by Monday.",ru:"К понедельнику я уже пришлю тебе договор."}},{en:"By the time + present",ru:"Точкой в будущем может быть другое событие: by the time + present simple, а в главной части will have + V3. Картинка «ты придёшь, а уже всё».",example:{en:"By the time you wake up, we'**ll have landed** in Dubai.",ru:"Когда ты проснёшься, мы уже приземлимся в Дубае."}},{en:"Totals by a future point",ru:"Подводим итог к моменту в будущем: сколько всего будет сделано или сколько продлится состояние. Глаголы состояния (know, be, have) не ставим в -ing, поэтому срок с ними считаем через will have + V3: In June I'll have known him for ten years.",example:{en:"By the end of this trip, we'**ll have visited** six countries.",ru:"К концу этой поездки мы побываем в шести странах."}},{en:"Confident guess about now",ru:"Иногда will have + V3 — не будущее, а уверенная догадка о том, что уже случилось: «наверняка уже». Обычно с by now.",example:{en:"It's nine already, so they'**ll have landed** by now.",ru:"Уже девять, так что они наверняка уже приземлились."}}],signals:[{word:"by + time",note:"by Friday, by 6 pm — «к», а не «до» (until). Просто will тоже возможно: I'll finish it by Friday"},{word:"by then",note:"«к тому времени»"},{word:"by the time + present simple",note:"by the time you come — без will после by the time"},{word:"by the end of…",note:"by the end of the week / month / year"},{word:"before + present simple",note:"I'll have left before you get here"},{word:"already",note:"I'll already have left / I'll have already left — оба порядка верны"},{word:"for + period",note:"срок до точки в будущем: for ten years"},{word:"by now",note:"уверенная догадка: they'll have arrived by now"}],versus:[{tense:"future-simple",ru:"Will + V1: ты проснёшься, и тогда я займусь завтраком. Will have + V3: к твоему пробуждению я уже уйду, действие закончится раньше.",a:{en:"When you wake up, I'**ll have left** for work.",ru:"Когда ты проснёшься, я уже уйду на работу."},b:{en:"When you wake up, I'**ll make** breakfast.",ru:"Когда ты проснёшься, я приготовлю завтрак."}},{tense:"future-perfect-continuous",ru:"Future perfect — результат и количество: сколько будет сделано. Future perfect continuous — сколько времени будет длиться процесс (for + срок).",a:{en:"By June I'**ll have written** five chapters.",ru:"К июню я напишу пять глав."},b:{en:"By June I'**ll have been writing** this book for a year.",ru:"В июне будет год, как я пишу эту книгу."}},{tense:"past-perfect",ru:"Логика одна и та же: «к моменту X уже случилось». Точка в прошлом — had + V3, точка в будущем — will have + V3.",a:{en:"By the time Mum gets home, we'**ll have cleaned** the flat.",ru:"К приходу мамы мы уже уберём квартиру."},b:{en:"By the time Mum got home, we **had cleaned** the flat.",ru:"К приходу мамы мы уже убрали квартиру."}}],mistakes:[{wrong:"By the time you will arrive, we will have eaten.",right:"By the time you arrive, we will have eaten.",why:"После by the time будущее передаём present simple, а will оставляем только в главной части."},{wrong:"The plumber will fixed the leak by tonight.",right:"The plumber will have fixed the leak by tonight.",why:"V3 без have не работает: между will и V3 обязательно стоит have."},{wrong:"She will has left by then.",right:"She will have left by then.",why:"После will всегда have, никогда has, даже с he, she, it."},{wrong:"I will have finish the slides by noon.",right:"I will have finished the slides by noon.",why:"После have нужна V3: finished, written, done, а не V1."},{wrong:"They will have repaired the road until May.",right:"They will have repaired the road by May.",why:"«К маю» (срок) — это by; until значит «до… (всё это время)» и нужен для длительности."},{wrong:"In June I will know him for ten years.",right:"In June I will have known him for ten years.",why:"«Будет десять лет, как я его знаю» — это срок до точки в будущем: will have + V3."}],trick:"Перенесись в ту точку будущего и оглянись назад: если дело там уже сделано, это will have + V3. Русские подсказки: «к пятнице уже…», «успею к…», а «не успею к шести» = I won't have finished by six.",examples:[{en:"Don't worry, I'**ll have packed** everything by the time the taxi comes.",ru:"Не переживай, к приезду такси я уже всё соберу."},{en:"By the time you get here, we'**ll have eaten** all the pizza.",ru:"Пока ты доберёшься, мы уже съедим всю пиццу."},{en:"The team **will have fixed** the bug by tomorrow morning.",ru:"К завтрашнему утру команда уже исправит баг."},{en:"She **won't have finished** her shift by eight, so let's meet at nine.",ru:"К восьми она ещё не закончит смену, так что давай встретимся в девять."},{en:"**Will** you **have finished** the slides by the meeting?",ru:"Ты успеешь доделать слайды к встрече?"},{en:"By the end of the year, we'**ll have hired** ten new developers.",ru:"К концу года мы наймём десять новых разработчиков."},{en:"Next month my parents **will have been** married for forty years.",ru:"В следующем месяце будет сорок лет, как мои родители женаты."},{en:"Max left an hour ago, so he'**ll have got** home by now.",ru:"Макс ушёл час назад, так что он наверняка уже дома."},{en:"I'm afraid we **won't have saved** enough for a car by summer.",ru:"Боюсь, к лету мы ещё не накопим на машину."},{en:"Call after nine: the kids **will have gone** to bed by then.",ru:"Звони после девяти: дети к тому времени уже лягут спать."}],exercises:[{id:"fp-anna-design",type:"choice",prompt:"By Friday, Anna ___ the design for the new app.",options:["will has finished","will have finished","will finished","has finished"],answer:1,rule:"Future perfect: will have + V3 (never will has)",explain:"After will, always use have, even with she: will have finished. 'Has finished' is present perfect and doesn't go with a future point like 'by Friday'.",ruHint:"will + have + V3 для всех лиц: Anna will have finished."},{id:"fp-gone-to-bed",type:"fill",before:"Don't call me at eleven: I ",after:" to bed by then.",answers:["will have gone","will have already gone","will already have gone"],base:"go",rule:"Done before a future point → will have + V3",explain:"By eleven I'll already be in bed: the action is finished before that point, so use will have + V3. The V3 of go is gone.",ruHint:"К одиннадцати я уже лягу спать — will have gone."},{id:"fp-dinner-ready",type:"choice",prompt:"When the guests arrive at seven, we ___ the table already, so they can sit down straight away.",options:["will lay","laid","will have laid","lay"],answer:2,rule:"Ready before that moment → will have + V3",explain:"Already and 'sit down straight away' show the table is ready before the guests arrive: will have laid. 'Will lay' would mean we start when they arrive.",ruHint:"К приходу гостей стол уже накрыт — will have laid."},{id:"fp-by-march",type:"errorTap",sentence:"We will have moved to the new office until March.",wrong:8,correct:"We will have moved to the new office by March.",rule:"Deadline → by March, not until March",explain:"A deadline takes by: by March means 'not later than March'. Until is for something that continues up to that time.",ruHint:"«К марту» — by March; until = «до… (всё время)»."},{id:"fp-concert-not-started",type:"fill",before:"Relax, we can leave at eight: the concert ",after:" by the time we get there.",answers:["won't have started","won't even have started","won't have even started"],base:"not / start",rule:"Negative: won't have + V3",explain:"When we get there, the start is still in the future, so use the negative future perfect: won't have started.",ruHint:"К нашему приходу концерт ещё не начнётся — won't have started."},{id:"fp-checked-in",type:"errorTap",sentence:"By the time you will get to the airport, I'll have checked in.",wrong:4,correct:"By the time you get to the airport, I'll have checked in.",rule:"by the time + present simple, not will",explain:"After by the time, use present simple for the future: by the time you get. Will goes only in the main part: I'll have checked in.",ruHint:"После by the time — без will: by the time you get."},{id:"fp-known-ten-years",type:"choice",prompt:"By next June, I ___ Max for ten years: we met at university.",options:["will have been knowing","will know","know","will have known"],answer:3,rule:"State verb + for + future point → will have + V3",explain:"We count ten years up to next June, so use future perfect. Know is a state verb, so no -ing: will have known.",ruHint:"«Будет десять лет, как я знаю Макса» — will have known, без -ing."},{id:"fp-finished-by-friday",type:"reorder",words:["will","you","have","finished","the","report","by","Friday"],end:"?",alt:[["by","Friday","will","you","have","finished","the","report"]],rule:"Question: Will + subject + have + V3?",explain:"In the question, only will goes before the subject; have and V3 stay after it: Will you have finished…?",ruHint:"«Ты успеешь закончить отчёт к пятнице?» — Will you have finished…?"}]},{id:"future-perfect-continuous",group:"future",name:"Future Perfect Continuous",ruName:"Будущее совершённое длительное",short:"How long an action will have been going on by a future point",idea:"Это время-счётчик: ты встаёшь в точку будущего и считаешь, сколько к ней уже длится процесс. «В июне будет два года, как я здесь работаю» = By June I'll have been working here for two years. Встречается редко и почти всегда с for + срок; с work, live, study часто говорят проще: I'll have worked here for two years.",category:"perfect",forms:[{label:"+",parts:["I / you / he / she / it / we / they","will have been","V-ing"],example:"By May, they'**ll have been building** the bridge for three years."},{label:"−",parts:["subject","won't have been","V-ing"],example:"She **won't have been working** here long by then."},{label:"?",parts:["How long","will","subject","have been","V-ing?"],example:"How long **will** you **have been living** here by June?"}],timeline:{marks:[{kind:"span",at:-.5,to:.6,label:"working here"},{kind:"point",at:.6,label:"June: two years"}],caption:"Stand at June and count back how long the work has lasted."},uses:[{en:"Duration up to a future point",ru:"Считаем, сколько времени процесс будет длиться к моменту в будущем. Нужны и точка (by June, next month, when you arrive), и срок (for two years, all day).",example:{en:"By June, I'**ll have been working** here for two years.",ru:"В июне будет два года, как я здесь работаю."}},{en:"Reason for a future state",ru:"Объясняем, почему человек в тот момент будет уставшим, голодным, мокрым: процесс шёл долго. Срок здесь часто без for: all day, all night.",example:{en:"She'll be exhausted when she lands: she'**ll have been travelling** all day.",ru:"Она будет без сил, когда приземлится: она же весь день будет в дороге."}},{en:"A simpler option often works",ru:"В живой речи это время нередко заменяют. С work, live, study, teach подходит и will have + V3, а ещё проще сказать It'll be two years in June since I started.",example:{en:"In June it'**ll be** two years since I **joined** the company.",ru:"В июне будет два года, как я в компании."}}],signals:[{word:"for + period",note:"for two years, for six hours: без срока это время почти не нужно"},{word:"by + time",note:"by June, by the end of the year: точка в будущем"},{word:"by the time + present simple",note:"by the time you arrive — без will после by the time"},{word:"when + present simple",note:"when she lands, she'll have been flying for 12 hours"},{word:"next month / in June",note:"точка без by: Next month I'll have been working here for a year"},{word:"all day / all night",note:"срок без for: she'll have been driving all day"},{word:"How long … by …?",note:"How long will you have been living here by June?"}],versus:[{tense:"future-perfect",ru:"Continuous считает время процесса (for six hours), работа ещё идёт. Простой future perfect считает результат: сколько будет сделано (fifty emails).",a:{en:"By the end of the day I'**ll have been answering** emails for six hours.",ru:"К концу дня будет шесть часов, как я отвечаю на письма."},b:{en:"By the end of the day I'**ll have answered** fifty emails.",ru:"К концу дня я отвечу на пятьдесят писем."}},{tense:"future-continuous",ru:"Future continuous — просто «в шесть я буду за рулём». Future perfect continuous — «в шесть будет уже пять часов, как я за рулём»: есть отрезок до точки.",a:{en:"At six I'**ll have been driving** for five hours.",ru:"В шесть будет уже пять часов, как я за рулём."},b:{en:"At six I'**ll be driving**.",ru:"В шесть я буду за рулём."}},{tense:"present-perfect-continuous",ru:"Логика одна: «сколько уже длится». Считаем до сейчас — have been + -ing, до точки в будущем — will have been + -ing.",a:{en:"In May I'**ll have been learning** English for three years.",ru:"В мае будет три года, как я учу английский."},b:{en:"I'**ve been learning** English for three years.",ru:"Я учу английский уже три года."}}],mistakes:[{wrong:"In May she will work here for ten years.",right:"In May she will have been working here for ten years.",why:"«Будет десять лет, как она работает» — это счёт до точки в будущем, will + V1 его не передаёт: нужно will have been + -ing."},{wrong:"Next month I will be working here for a year.",right:"Next month I will have been working here for a year.",why:"Will be + -ing — просто процесс в момент будущего, срок до точки он не считает: «будет год, как я здесь» = will have been working."},{wrong:"By 2027 I will have been knowing her for ten years.",right:"By 2027 I will have known her for ten years.",why:"Know, be, have (иметь), own — глаголы состояния, они не ставятся в -ing: только will have + V3."},{wrong:"Next week I will have been living here since three months.",right:"Next week I will have been living here for three months.",why:"Срок — это for (for three months), а since ставим только перед точкой начала (since March)."},{wrong:"By the time we will land, we will have been flying for 12 hours.",right:"By the time we land, we will have been flying for 12 hours.",why:"После by the time будущее передаём present simple, will остаётся только в главной части."}],trick:"Формула-счётчик: точка в будущем + for + срок. Если по-русски получается «к июню будет уже два года, как…» и важна длительность процесса до этой точки, это will have been + -ing; нет срока — это время почти никогда не нужно. В разговоре то же часто говорят проще: It'll be two years in June since I started.",examples:[{en:"By March, Olga **will have been running** her own café for five years.",ru:"В марте будет пять лет, как Ольга держит своё кафе."},{en:"When she lands in Sydney, she'**ll have been travelling** for almost a day.",ru:"Когда она приземлится в Сиднее, она будет в дороге уже почти сутки."},{en:"Next month we'**ll have been living** in Berlin for five years.",ru:"В следующем месяце будет пять лет, как мы живём в Берлине."},{en:"By the time the meeting ends, we'**ll have been talking** for three hours.",ru:"К концу встречи мы проговорим уже три часа."},{en:"How long **will** you **have been studying** English by the end of the year?",ru:"Сколько к концу года будет, как ты учишь английский?"},{en:"The kids will be starving: they'**ll have been playing** football all afternoon.",ru:"Дети придут голодными: они же полдня будут гонять мяч."},{en:"Take your time: when you get here, we **won't have been waiting** long.",ru:"Не торопись: к твоему приезду мы прождём совсем недолго."},{en:"In 2027 Dad **will have been teaching** at the same school for thirty years.",ru:"В 2027 году будет тридцать лет, как папа преподаёт в одной и той же школе."},{en:"By the time you read this, I'**ll have been hiking** for a week.",ru:"Когда ты это прочитаешь, я уже неделю буду в походе."},{en:"At midnight the servers **will have been running** without a break for 100 days.",ru:"В полночь будет 100 дней, как серверы работают без перерыва."}],exercises:[{id:"fpc-tom-bank",type:"choice",prompt:"By June, Tom ___ at the bank for ten years.",options:["will have been working","will has been working","will been working","has been working"],answer:0,rule:"Future perfect continuous: will have been + -ing",explain:"We count ten years up to a future point (June): will have been working. After will, always have, never has; 'has been working' counts only up to now.",ruHint:"В июне будет десять лет, как Том работает в банке — will have been working."},{id:"fpc-been-working",type:"fill",before:"By the end of this month, I'll have been ",after:" on this project for a year.",answers:["working"],base:"work",rule:"After will have been → -ing",explain:"The continuous part needs the -ing form after been: will have been working.",ruHint:"После been — форма на -ing: working."},{id:"fpc-anna-tokyo",type:"choice",prompt:"When Anna lands in Tokyo, she ___ for almost a whole day, so don't plan anything for that evening.",options:["will travel","will be travelling","will have been travelling","travels"],answer:2,rule:"Duration up to a future point → will have been + -ing",explain:"When she lands, the journey has already lasted almost a day, and that explains why she'll be tired: will have been travelling.",ruHint:"К моменту посадки она уже почти сутки будет в дороге — will have been travelling."},{id:"fpc-by-the-time-get",type:"fill",before:"By the time you ",after:" home, I'll have been cooking for three hours!",answers:["get"],base:"get",rule:"by the time + present simple, not will",explain:"After by the time, use present simple for the future: by the time you get home. Will goes only in the main part.",ruHint:"После by the time — без will: by the time you get."},{id:"fpc-driving-by-noon",type:"reorder",words:["by","noon","we'll","have","been","driving","for","six","hours"],alt:[["we'll","have","been","driving","for","six","hours","by","noon"]],rule:"will have been + -ing + for + period",explain:"The form goes will + have + been + -ing, and the period follows with for: we'll have been driving for six hours.",ruHint:"«К полудню мы будем в пути уже шесть часов» — we'll have been driving for six hours."},{id:"fpc-since-for",type:"errorTap",sentence:"When you arrive, I'll have been waiting since two hours.",wrong:7,correct:"When you arrive, I'll have been waiting for two hours.",rule:"Length of time → for; starting point → since",explain:"Two hours is a length of time, so use for. Since goes with a starting point, like since two o'clock.",ruHint:"«Два часа» — for two hours; since — только «с какого момента»."},{id:"fpc-had-this-flat",type:"choice",prompt:"By 2030, we ___ this flat for twenty years.",options:["will have been having","will have had","will have","have had"],answer:1,rule:"State verbs (know, have, own) → will have + V3",explain:"Have meaning 'own' is a state verb, so it doesn't take -ing. Use future perfect: will have had.",ruHint:"have = «иметь» — глагол состояния, без -ing: will have had."},{id:"fpc-at-six-driving",type:"choice",prompt:"At 6 pm tomorrow I ___ to Kazan, so text me instead of calling.",options:["will be driving","will have been driving","will have driven","drive"],answer:0,rule:"In progress at a future moment, no period → will be + -ing",explain:"There is no 'for + period' to count, only a moment when I'm in the middle of driving: will be driving.",ruHint:"Нет срока, просто «буду за рулём в шесть» — future continuous: will be driving."}]},{id:"time-clauses",group:"key",name:"Time Clauses: when, if, until",ruName:"Будущее после when, if, until",short:"No will after when, if, as soon as, until: present for the future",idea:"После when, if, as soon as, before, after, until, once, by the time и in case будущее передаём настоящим временем, обычно present simple, а will остаётся только в главной части. По-русски «когда я приду» звучит в будущем, а по-английски when I come: будущее уже видно из главной части, и второй раз через will его не показывают. Если важно, что действие к тому моменту закончится, берём present perfect: after I've finished.",category:"conditionals",forms:[{label:"+",parts:["will + V1","when / if / until…","present simple"],example:"I'll call you when I **land**."},{label:"Done first",parts:["will + V1","after / when / once…","present perfect"],example:"We'll leave after we'**ve had** breakfast."},{label:"−",parts:["if / when / in case…","don't / doesn't + V1"],example:"If you **don't hurry**, we'll miss the train."},{label:"?",parts:["Will","subject","V1","when / if…","present simple?"],example:"Will you text me when you **get** home?"},{label:"Clause first",parts:["When / If + present,","will + V1"],example:"As soon as she **arrives**, we'll start."}],timeline:{marks:[{kind:"point",at:.35,label:"when I land"},{kind:"point",at:.5,label:"I'll call you"}],caption:"Both are in the future, but only the main part takes will."},uses:[{en:"Future after time words",ru:"После when, as soon as, before, after, until, once и by the time будущее передаём настоящим временем, обычно present simple. Will стоит только в главной части.",example:{en:"I'll text you as soon as I **get** to the hotel.",ru:"Напишу тебе, как только доберусь до отеля."}},{en:"Conditions: if, unless, in case",ru:"С if (если), unless (если не) и in case (на случай, если) то же правило: present simple, хотя по-русски звучит будущее.",example:{en:"If the bank **approves** the loan, we'll buy the flat.",ru:"Если банк одобрит кредит, мы купим квартиру."}},{en:"Finished first: present perfect",ru:"Если важно, что одно действие закончится раньше другого, после when, after, as soon as, once, until можно взять present perfect: when I've finished = «когда уже закончу». Если действия одновременные (When I see him, I'll tell him), только present simple.",example:{en:"You can borrow the book when I'**ve read** it.",ru:"Можешь взять книгу, когда я её дочитаю."}},{en:"When will is correct",ru:"Если when — это вопрос «когда?», а if — «ли» (I don't know when…, I wonder if…), это уже не время и не условие, и will нужен. Изредка will после if значит вежливое «будьте добры» (If you'll wait here, I'll get the manager), но это особый случай.",example:{en:"I don't know if she'**ll come** to the party.",ru:"Не знаю, придёт ли она на вечеринку."}}],signals:[{word:"when",note:"«когда»: when I get home"},{word:"if",note:"«если»; но if = «ли» (whether) — will можно"},{word:"as soon as",note:"«как только»"},{word:"before",note:"«до того как, перед тем как»"},{word:"after",note:"часто с present perfect: after I've finished"},{word:"until",note:"«пока не»: until you come back — без второго not"},{word:"once",note:"«как только, после того как»"},{word:"by the time",note:"«к тому времени, как»"},{word:"in case",note:"«на случай, если»; «в случае, если» — это просто if"},{word:"unless",note:"= if not: unless you hurry"}],versus:[{tense:"future-simple",ru:"В первой фразе when = «в тот момент, когда»: это время, will нельзя. Во второй when = «во сколько?», это вопрос внутри фразы, и will нужен.",a:{en:"Let me know when you **arrive**.",ru:"Дай знать, когда приедешь (напиши, как будешь на месте)."},b:{en:"Let me know when you'**ll arrive**.",ru:"Сообщи, во сколько приедешь."}},{tense:"present-perfect",ru:"Обе фразы правильные: present perfect подчёркивает, что сначала дело будет полностью закончено. Если действия одновременные (When I see him, I'll tell him), только present simple.",a:{en:"I'll send you the file when I **finish** it.",ru:"Пришлю тебе файл, когда закончу его."},b:{en:"I'll send you the file when I'**ve finished** it.",ru:"Пришлю тебе файл, когда полностью его закончу."}},{tense:"conditionals",ru:"Реальное будущее: present после if и will в главной части. Мечта или что-то маловероятное: past после if и would.",a:{en:"If we **get** the contract, we'**ll open** an office in Dubai.",ru:"Если мы получим контракт, откроем офис в Дубае."},b:{en:"If we **got** the contract, we'**d open** an office in Dubai.",ru:"Если бы мы получили контракт, мы бы открыли офис в Дубае."}}],mistakes:[{wrong:"When the meeting will finish, I'll call you.",right:"When the meeting finishes, I'll call you.",why:"После when — present simple, даже если по-русски «когда закончится»; will только в главной части."},{wrong:"I'll call you as soon as I will finish.",right:"I'll call you as soon as I finish.",why:"As soon as работает как when: present simple (или present perfect: as soon as I've finished)."},{wrong:"We'll wait here until the rain doesn't stop.",right:"We'll wait here until the rain stops.",why:"Until уже значит «пока не», поэтому второе not не нужно: until the rain stops."},{wrong:"If you will need help, call me.",right:"If you need help, call me.",why:"If в значении «если» — present simple, даже когда речь о будущем."},{wrong:"Take an umbrella in case it will rain.",right:"Take an umbrella in case it rains.",why:"In case («на случай, если») подчиняется тому же правилу: present simple без will."},{wrong:"I'm not sure if Max comes tomorrow.",right:"I'm not sure if Max will come tomorrow.",why:"Здесь if = «ли» (не знаю, придёт ли Макс): это вопрос, а не условие, поэтому will нужен."}],trick:"Будущее уже показано в главной части (I'll call you), в кусок с when или if второй will не ставим: when I land, а не when I will land. Проверка: если кусок отвечает на «в какой момент?» или «при каком условии?», will туда не ставим. Если же when — это вопрос «когда?», а if — «ли» (подставь whether), will нужен: Let me know when you'll arrive.",examples:[{en:"I'll text you as soon as I **land** in Istanbul.",ru:"Напишу тебе, как только приземлюсь в Стамбуле."},{en:"When you **get** to the office, ask for Maria at reception.",ru:"Когда доберёшься до офиса, спроси Марию на ресепшене."},{en:"We won't start the meeting until everyone **arrives**.",ru:"Мы не начнём встречу, пока все не придут."},{en:"Can you call me before you **leave** the office?",ru:"Можешь позвонить мне перед тем, как выйдешь из офиса?"},{en:"I'll send you the invoice after I'**ve checked** the numbers.",ru:"Пришлю тебе счёт, после того как проверю цифры."},{en:"If the client **doesn't reply** by Friday, we'll call them.",ru:"Если клиент не ответит к пятнице, мы ему позвоним."},{en:"Once the visa **is** ready, we'll book the flights.",ru:"Как только виза будет готова, забронируем билеты."},{en:"Take a jacket in case it **gets** cold in the evening.",ru:"Возьми куртку на случай, если вечером похолодает."},{en:"By the time we **get** there, the shop will have closed.",ru:"Пока мы доберёмся, магазин уже закроется."},{en:"I'm not sure when the results **will be** ready, maybe next week.",ru:"Не знаю точно, когда будут готовы результаты, может, на следующей неделе."}],exercises:[{id:"tc-when-get-home",type:"choice",prompt:"We'll have dinner when Dad ___ home.",options:["will get","gets","would get","got"],answer:1,rule:"when + present simple for the future",explain:"After when, the future is shown with present simple: when Dad gets home. Will goes only in the main part: we'll have dinner.",ruHint:"«Когда папа придёт» — when Dad gets home, без will."},{id:"tc-plane-lands",type:"fill",before:"I'll text you as soon as the plane ",after:".",answers:["lands","has landed"],base:"land",rule:"as soon as + present simple (it + -s)",explain:"As soon as works like when: present simple for the future. With it (the plane), add -s: lands. Has landed is also fine.",ruHint:"«Как только самолёт приземлится» — as soon as the plane lands."},{id:"tc-until-come-back",type:"choice",prompt:"Don't leave the office until I ___ back.",options:["will come","don't come","come","won't come"],answer:2,rule:"until + present simple, no extra not",explain:"Until already means 'up to the moment when', so no not and no will: until I come back.",ruHint:"«Пока я не вернусь» — until I come back, без not и без will."},{id:"tc-in-case-card",type:"errorTap",sentence:"Take some cash in case they'll want a tip.",wrong:5,correct:"Take some cash in case they want a tip.",rule:"in case + present simple, not will",explain:"In case follows the same rule as if and when: present simple for the future, so no will: in case they want a tip.",ruHint:"«На случай, если там попросят чаевые» — in case they want a tip, без will."},{id:"tc-after-finished",type:"fill",before:"You can go home after you ",after:" the report.",answers:["have finished","finish"],base:"finish",rule:"after + present perfect or present simple, not will",explain:"After takes present perfect (have finished) to show the report is done first, or present simple (finish). Never will.",ruHint:"«После того как закончишь» — after you've finished (или after you finish)."},{id:"tc-once-signed",type:"reorder",words:["once","you've","signed","the","contract","we'll","book","the","flights"],alt:[["we'll","book","the","flights","once","you've","signed","the","contract"]],rule:"once + present perfect; will only in the main part",explain:"Once means 'as soon as, after'. It takes present perfect for the finished action (you've signed); will goes in the main part (we'll book).",ruHint:"«Как только подпишешь договор, забронируем билеты» — once you've signed the contract, we'll book…"},{id:"tc-by-the-time-message",type:"errorTap",sentence:"By the time you will get this message, I'll be on the plane.",wrong:4,correct:"By the time you get this message, I'll be on the plane.",rule:"by the time + present simple, not will",explain:"By the time is a time phrase like when: present simple for the future, so delete will: by the time you get.",ruHint:"«К тому времени, как ты получишь» — by the time you get, без will."},{id:"tc-wonder-if-rain",type:"choice",prompt:"I wonder if it ___ tomorrow: we want to go hiking.",options:["rains","will rain","rain","rained"],answer:1,rule:"if = whether → will is correct",explain:"Here if means whether: it is a question, not a condition. So the future takes will: I wonder if it will rain.",ruHint:"«Интересно, будет ли дождь» — if = «ли», поэтому will."}]},{id:"conditionals",group:"key",name:"Conditionals",ruName:"Условные предложения",short:"If-sentences: is it real or not, and is it about now or the past?",idea:"Каждое «если» проверяй двумя вопросами: это реально или фантазия? и это про сейчас/будущее или про прошлое? Реальное будущее идёт с present после if (If it rains, we'll stay at home), а нереальное делает шаг назад во времени: фантазия о сейчас или будущем берёт past, фантазия о прошлом — had + V3. Русское «если бы» — это всегда нереальность, то есть второй, третий или смешанный тип.",category:"conditionals",forms:[{label:"Zero",parts:["If + present","present"],example:"If you **heat** ice, it **melts**."},{label:"First",parts:["If + present","will + V1"],example:"If you **leave** now, you'**ll catch** the bus."},{label:"Second",parts:["If + past","would + V1"],example:"If I **had** more time, I'**d learn** Spanish."},{label:"Third",parts:["If + had + V3","would have + V3"],example:"If you **had asked** me, I **would have helped**."},{label:"Mixed",parts:["If + had + V3","would + V1 (now)"],example:"If I **had studied** IT, I **would be** a developer now."}],timeline:{marks:[{kind:"point",at:-.6,label:"If I had known (3rd)"},{kind:"span",at:-.15,to:.35,label:"If I knew (2nd)"},{kind:"point",at:.65,label:"If it rains (1st)"}],caption:"Real ifs look ahead; unreal ifs step one tense back."},uses:[{en:"Zero: always true",ru:"Факты, законы природы, правила и твои привычные реакции: если А, то всегда Б. В обеих частях present simple, и if почти всегда можно заменить на when.",example:{en:"If you **mix** red and blue, you **get** purple.",ru:"Если смешать красный и синий, получится фиолетовый."}},{en:"First: real future",ru:"Ситуация в будущем, которая вполне может случиться. После if — present simple (смысл будущий, но без will), в главной части — will, can, may или повелительное наклонение.",example:{en:"If the client **agrees**, we'**ll start** on Monday.",ru:"Если клиент согласится, мы начнём в понедельник."}},{en:"Second: unreal now",ru:"То самое «если бы» про сейчас или маловероятное будущее. После if — past simple (это не прошлое, а знак нереальности), в главной части — would + V1; с be часто were для всех лиц.",example:{en:"If we **lived** by the sea, we **would swim** every day.",ru:"Если бы мы жили у моря, мы бы купались каждый день."}},{en:"Third: unreal past",ru:"«Если бы» про прошлое, которое уже не изменить: сожаления и упущенные шансы. После if — had + V3, в главной части — would have + V3 (или could / might have + V3).",example:{en:"If we **had taken** a taxi, we **would have arrived** on time.",ru:"Если бы мы взяли такси, мы бы приехали вовремя."}},{en:"Mixed: past → now",ru:"Условие в прошлом, а последствие видно сейчас: If + had + V3, would + V1 (часто с now). Бывает и наоборот: If I were braver, I would have said yes (нереальное «вообще» → прошлое).",example:{en:"If he **had taken** the job in Berlin, he **would live** in Germany now.",ru:"Если бы он тогда согласился на работу в Берлине, он бы сейчас жил в Германии."}}],signals:[{word:"if",note:"после if про будущее — present, без will"},{word:"unless",note:"= if … not; само уже отрицание: unless you hurry"},{word:"when",note:"when — точно случится, if — может быть; после обоих без will"},{word:"as long as / provided (that)",note:"«при условии, что»; обычно с реальным условием"},{word:"in case",note:"«на случай, если» — это не if: I'll take a book in case I get bored"},{word:"If I were you",note:"совет «на твоём месте»; were для всех лиц, was — разговорный вариант"},{word:"imagine / suppose",note:"+ past для фантазии: Imagine you lived in Bali"},{word:"I wish / if only",note:"та же логика шага назад: I wish I knew = жаль, что не знаю"}],versus:[{tense:"time-clauses",ru:"If — может случиться, а может и нет; when — точно случится, вопрос только когда. Грамматика одна: после обоих present, will только в главной части.",a:{en:"If I **see** Tom, I'**ll tell** him.",ru:"Если увижу Тома, скажу ему."},b:{en:"When I **see** Tom, I'**ll tell** him.",ru:"Когда увижу Тома, скажу ему."}},{tense:"past-simple",ru:"Во втором типе past после if — не прошлое, а нереальность сейчас: машины у нас нет. Обычный past simple — про то, что действительно было.",a:{en:"If we **had** a car, we **would drive** to work.",ru:"Если бы у нас была машина, мы бы ездили на ней на работу."},b:{en:"When we **had** a car, we **drove** to work.",ru:"Когда у нас была машина, мы ездили на ней на работу."}},{tense:"past-perfect",ru:"Форма та же — had + V3, но в третьем типе это нереальность (на самом деле не забронировали), а в past perfect — реальный факт, случившийся раньше другого.",a:{en:"If we **had booked** the hotel in May, it **would have been** cheaper.",ru:"Если бы мы забронировали отель в мае, было бы дешевле."},b:{en:"We **had booked** the hotel in May, before the prices went up.",ru:"Мы забронировали отель ещё в мае, до того как выросли цены."}}],mistakes:[{wrong:"If the price will go down, we will buy it.",right:"If the price goes down, we will buy it.",why:"После if про будущее нужен present: will ставится только в главную часть."},{wrong:"If I would have time, I would help you.",right:"If I had time, I would help you.",why:"Русское «бы» после if передаётся через past (had, knew, were), а would ставь в главную часть."},{wrong:"If you told me yesterday, I would help you.",right:"If you had told me yesterday, I would have helped you.",why:"Русское «если бы» одно на все времена, а в английском про прошлое нужны had + V3 и would have + V3."},{wrong:"If I am you, I would call her.",right:"If I were you, I would call her.",why:"«На твоём месте» — нереальная ситуация, поэтому If I were you, а не am."},{wrong:"I would have go there if I had known.",right:"I would have gone there if I had known.",why:"После would have всегда V3: gone, seen, done."},{wrong:"Unless you don't hurry, you'll miss the train.",right:"Unless you hurry, you'll miss the train.",why:"Unless уже значит «если не», второе отрицание не нужно."}],trick:"Задай два вопроса: это реально? и это про прошлое? Реальное будущее → If + present, will; «если бы» про сейчас или будущее → If + past, would + V1; «если бы» про прошлое → If + had + V3, would have + V3. Will и would для будущего и «бы» ставь в часть без if. Исключение — вежливость и желание: If you'd like…, If you would wait here, please… — тут would значит «хочешь, будь добр», а не «бы».",examples:[{en:"If I **drink** coffee after six, I **can't sleep**.",ru:"Если я пью кофе после шести, то не могу уснуть."},{en:"If the train **is** on time, we'**ll get** there by noon.",ru:"Если поезд придёт вовремя, мы будем там к полудню."},{en:"**Will** you **call** me if your flight **is delayed**?",ru:"Позвонишь мне, если твой рейс задержат?"},{en:"We **won't release** the update unless all the tests **pass**.",ru:"Мы выпустим обновление, только если пройдут все тесты."},{en:"If we **lived** closer to the office, we **wouldn't need** a car.",ru:"Если бы мы жили ближе к офису, нам не нужна была бы машина."},{en:"What **would** you **do** if you **lost** your passport abroad?",ru:"Что бы вы сделали, если бы потеряли паспорт за границей?"},{en:"If my sister **were** here, she **would know** what to do.",ru:"Если бы сестра была здесь, она бы знала, что делать."},{en:"If the taxi **hadn't been** late, we **wouldn't have missed** our flight.",ru:"Если бы такси не опоздало, мы бы успели на самолёт."},{en:"She **would have passed** the interview if she **had prepared** better.",ru:"Она бы прошла собеседование, если бы лучше подготовилась."},{en:"If she **had learned** English at school, she **wouldn't need** a tutor now.",ru:"Если бы она учила английский в школе, сейчас ей не нужен был бы репетитор."}],exercises:[{id:"cond-if-it-rains",type:"choice",prompt:"If it ___ on Saturday, we'll watch a film at home instead.",options:["will rain","rains","rained","would rain"],answer:1,rule:"Real future: If + present, will in the other part",explain:"This can really happen, so it is the first conditional: present after if (rains), will in the other part.",ruHint:"После if про будущее — present: If it rains, без will."},{id:"cond-no-will-after-if",type:"errorTap",sentence:"If the clients will like the design, we'll start next week.",wrong:3,correct:"If the clients like the design, we'll start next week.",rule:"No will after if: If + present for the future",explain:"In the if-part English uses present simple for the future: if the clients like. Will goes only in the main part.",ruHint:"«Если понравится» — всё равно present: if they like."},{id:"cond-if-we-had-flat",type:"fill",before:"If we ",after:" a bigger flat, we would invite you to stay with us.",answers:["had"],base:"have",rule:"Unreal now: If + past, would + V1",explain:"We don't have a bigger flat now, so this is unreal: past after if (had), would in the other part.",ruHint:"«Если бы у нас была квартира побольше» — If we had, а не If we would have."},{id:"cond-if-i-were-you",type:"choice",prompt:"If I ___ you, I'd talk to the team lead first.",options:["am","would be","were","will be"],answer:2,rule:"Advice: If I were you, I'd + V1",explain:"You can't be the other person, so this is unreal: If I were you. Were works for all persons here; was is informal.",ruHint:"«На твоём месте» = If I were you."},{id:"cond-would-have-caught",type:"fill",before:"If we had left ten minutes earlier, we ",after:" the train.",answers:["would have caught","could have caught","might have caught"],base:"catch",rule:"Unreal past: If + had + V3, would have + V3",explain:"We didn't leave earlier, so this is an unreal past: would have + V3 (caught). Could have or might have caught also work if you are less sure.",ruHint:"«Успели бы» про прошлое — would have caught."},{id:"cond-if-i-had-known",type:"choice",prompt:"Nobody told me about the party. If I ___ about it, I would have come.",options:["knew","have known","had known","would know"],answer:2,rule:"Past situation: If + had + V3, not If + past",explain:"The party is in the past, so the if-part needs had + V3: had known. 'If I knew' would be about now.",ruHint:"«Если бы» про прошлое — If I had known, а не If I knew."},{id:"cond-would-have-called",type:"reorder",words:["I","would","have","called","you","if","I","had","known"],alt:[["if","I","had","known","I","would","have","called","you"]],rule:"Third conditional: would have + V3 + if + had + V3",explain:"Unreal past: would have + V3 in the main part, had + V3 after if. Either part can come first.",ruHint:"Третий тип: would have called + if I had known."},{id:"cond-mixed-would-speak",type:"choice",prompt:"If she had moved to London, she ___ English much better now.",options:["would have spoken","would speak","will speak","spoke"],answer:1,rule:"Past condition, result now → would + V1",explain:"The condition is in the past (had moved), but 'now' shows the result is in the present, so use would + V1: would speak.",ruHint:"Условие в прошлом, результат сейчас — смешанный тип: would speak."}]},{id:"used-to",group:"key",name:"Used to, would, be used to",ruName:"«Раньше…» и «привык»",short:"Past habits and states that aren't true now (and be used to = accustomed)",idea:"Used to — это «раньше было так, а теперь нет»: I used to live in Kazan значит, что Казань уже в прошлом. Это не отдельное время, а оборот для привычек и состояний в прошлом, и он одинаков для всех лиц. Главная ловушка — похожее be used to + -ing: оно значит совсем другое, «привычно, привык».",category:"tense-choice",forms:[{label:"+",parts:["I / you / he / she / it / we / they","used to","V1"],example:"I **used to cycle** to work."},{label:"−",parts:["subject","didn't use to","V1"],example:"She **didn't use to drink** coffee."},{label:"?",parts:["Did","subject","use to","V1?"],example:"**Did** you **use to play** football?"},{label:"would",parts:["subject","would","V1 (actions only)"],example:"On Sundays Dad **would make** pancakes."},{label:"be used to",parts:["subject","am / is / are","used to","V-ing / noun"],example:"She'**s used to working** nights."},{label:"get used to",parts:["subject","get","used to","V-ing / noun"],example:"You'**ll get used to** the cold."}],timeline:{marks:[{kind:"repeat",at:-.9,to:-.3,label:"I used to cycle to work"},{kind:"point",at:0,label:"Now I drive"}],caption:"A past habit or state that stopped: it isn't true now."},uses:[{en:"Past habits",ru:"Регулярные действия в прошлом, которых больше нет. По-русски это обычно «раньше» + глагол несовершенного вида.",example:{en:"We **used to go** to the dacha every weekend.",ru:"Раньше мы каждые выходные ездили на дачу."}},{en:"Past states",ru:"Долгие состояния в прошлом: жить где-то, любить, иметь, быть. Для них подходит used to, а would нельзя.",example:{en:"There **used to be** a cinema on this street.",ru:"Раньше на этой улице был кинотеатр."}},{en:"would for past routines",ru:"В рассказе о прошлом повторяющиеся действия можно передать через would + V1, но только действия, не состояния. Обычно сначала задают рамку (used to, when we were kids), а дальше идёт would.",example:{en:"Every Sunday my grandma **would bake** pies for the whole family.",ru:"Каждое воскресенье бабушка пекла пироги на всю семью."}},{en:"be used to = accustomed",ru:"«Привычно, привык»: здесь to — предлог, поэтому дальше -ing или существительное. Be может стоять в любом времени: I'm / I was / I'll be used to.",example:{en:"I'**m used to working** with remote teams.",ru:"Мне привычно работать с удалёнными командами."}},{en:"get used to = adapt",ru:"Процесс «привыкать, привыкнуть». Конструкция та же: get used to + -ing или существительное.",example:{en:"You'**ll** soon **get used to driving** on the left.",ru:"Ты скоро привыкнешь ездить по левой стороне."}}],signals:[{word:"used to + V1",note:"«раньше…, а теперь нет»"},{word:"didn't use to / never used to",note:"после did — use без -d; never used to — частая разговорная замена"},{word:"Did you use to …?",note:"в вопросе тоже use без -d"},{word:"would + V1",note:"только повторяющиеся действия, не состояния"},{word:"be used to + -ing / noun",note:"= привычно (состояние)"},{word:"get used to + -ing / noun",note:"= привыкать, привыкнуть (процесс)"},{word:"when I was a kid / at school",note:"типичная рамка для used to и would"},{word:"not … anymore",note:"пара к used to: I used to smoke, I don't smoke anymore (в BrE часто any more)"},{word:"usually / these days",note:"привычки сейчас — present simple, а не use to"}],versus:[{tense:"past-simple",ru:"Used to — долгая привычка, которой больше нет; past simple тоже может описать привычку, но не подчёркивает «теперь иначе». Если говоришь, сколько раз или как долго (three times, for a year), или про короткий недавний период (last week), нужен только past simple.",a:{en:"We **used to eat out** every Friday.",ru:"Раньше мы каждую пятницу ужинали в ресторане."},b:{en:"We **ate out** three times last week.",ru:"На прошлой неделе мы три раза ужинали в ресторане."}},{tense:"present-simple",ru:"Used to — только про прошлое. Для привычки сейчас нужен present simple (часто с usually); формы «I use to» в этом смысле нет.",a:{en:"She **used to work** from home.",ru:"Раньше она работала из дома (а теперь нет)."},b:{en:"She usually **works** from home.",ru:"Обычно она работает из дома."}},{tense:"present-perfect",ru:"Used to — раньше жили, а теперь нет. Present perfect с since — живут там до сих пор.",a:{en:"They **used to live** in Samara.",ru:"Раньше они жили в Самаре (теперь нет)."},b:{en:"They'**ve lived** in Samara since 2015.",ru:"Они живут в Самаре с 2015 года."}}],mistakes:[{wrong:"I use to get up at seven.",right:"I usually get up at seven.",why:"Привычка сейчас — present simple (часто с usually): used to бывает только про прошлое."},{wrong:"Did you used to live here?",right:"Did you use to live here?",why:"После did глагол всегда в V1, поэтому use to без -d."},{wrong:"I'm used to work late.",right:"I'm used to working late.",why:"В be used to слово to — предлог, после него нужен -ing или существительное."},{wrong:"I used to the noise now.",right:"I'm used to the noise now.",why:"Смысл «сейчас привычно» требует be: I'm used to; без be used to значит «раньше…» и требует глагол."},{wrong:"When I was a child, I would have a dog.",right:"When I was a child, I used to have a dog.",why:"Would не употребляют для состояний (have, be, live, like): здесь только used to или past simple."},{wrong:"I used to live in Kazan for five years.",right:"I lived in Kazan for five years.",why:"Когда называешь срок или число раз (for five years, three times), нужен past simple, а не used to."}],trick:"Посмотри, есть ли перед used to глагол be или get. Нет — это «раньше было, а теперь нет», дальше V1: I used to work late. Есть — это «привычно, привыкнуть», дальше -ing или существительное: I'm used to working late (исключение — пассив от use: It's used to cut glass = им режут стекло).",examples:[{en:"We **used to live** in a tiny flat, but we moved to a house in 2021.",ru:"Раньше мы жили в крошечной квартире, но в 2021 году переехали в дом."},{en:"My dad **used to smoke**, but he gave up ten years ago.",ru:"Раньше папа курил, но бросил десять лет назад."},{en:"She **didn't use to like** coffee, but now she drinks three cups a day.",ru:"Раньше она не любила кофе, а теперь пьёт по три чашки в день."},{en:"**Did** you **use to play** any sports at school?",ru:"Вы в школе занимались каким-нибудь спортом?"},{en:"There **used to be** a small bookshop here, but it closed last year.",ru:"Раньше здесь был маленький книжный, но в прошлом году он закрылся."},{en:"Every summer we **would rent** a house by the lake and swim all day.",ru:"Каждое лето мы снимали дом у озера и целыми днями купались."},{en:"We **never used to argue** about money.",ru:"Раньше мы никогда не спорили из-за денег."},{en:"I'**m used to working** with clients in different time zones.",ru:"Мне привычно работать с клиентами из разных часовых поясов."},{en:"It took me a month to **get used to** the open-plan office.",ru:"Мне понадобился месяц, чтобы привыкнуть к опенспейсу."},{en:"**Is** your team **used to** the new system yet?",ru:"Твоя команда уже привыкла к новой системе?"}],exercises:[{id:"ut-used-to-live",type:"choice",prompt:"I ___ in Kazan, but now I live in Moscow.",options:["used to live","use to live","am used to living","was used to live"],answer:0,rule:"Past state, not true now → used to + V1",explain:"This was true in the past and isn't true now, so use used to + V1: used to live. 'Am used to living' means you are accustomed to it.",ruHint:"«Раньше, а теперь нет» — used to + V1."},{id:"ut-did-you-use-to",type:"fill",before:"Did you ",after:" work in a bank before you moved to IT?",answers:["use to"],base:"used to",rule:"After did: use to (no -d)",explain:"After did the verb is always in the base form, so used loses its -d: Did you use to…?",ruHint:"После did — use to, без -d."},{id:"ut-usually-cycle",type:"choice",prompt:"These days I ___ to work because it's faster than the bus.",options:["use to cycle","used to cycle","am used to cycle","usually cycle"],answer:3,rule:"Habit now → present simple, not 'use to'",explain:"'These days' is about now. Used to is only for the past, and there is no 'I use to' for present habits: use present simple.",ruHint:"Привычка сейчас — present simple: I usually cycle."},{id:"ut-grandad-would-tell",type:"choice",prompt:"When we were kids, our grandad ___ us stories every evening.",options:["is used to telling","would tell","use to tell","used to telling"],answer:1,rule:"Repeated past action → would + V1 (or used to)",explain:"Telling stories is a repeated action in the past, so would + V1 works (used to tell would be fine too). The other options are wrong forms.",ruHint:"Повторяющееся действие в прошлом — would tell (или used to tell)."},{id:"ut-would-have-hair",type:"errorTap",sentence:"When I was a student, I would have long hair.",wrong:6,correct:"When I was a student, I used to have long hair.",rule:"States (have, be, live) → used to, not would",explain:"Having long hair is a state, not a repeated action. Would works only for actions, so use used to have (or simply: I had long hair).",ruHint:"Состояние (have) — только used to, не would."},{id:"ut-used-to-getting-up",type:"fill",before:"Don't worry about the early start: I'm used to ",after:" up at six.",answers:["getting"],base:"get",rule:"be used to + -ing = accustomed",explain:"In be used to, to is a preposition, so the next verb takes -ing: I'm used to getting up.",ruHint:"be used to («привычно») + -ing: getting."},{id:"ut-am-used-to-noise",type:"choice",prompt:"It was hard at first, but now I ___ the noise from the street.",options:["used to","use to","am used to","get used"],answer:2,rule:"Accustomed now → be used to + noun",explain:"Now the noise is normal for you, so use be used to + noun: I'm used to the noise. 'I used to the noise' has no verb.",ruHint:"«Сейчас уже привычно» — I'm used to the noise."},{id:"ut-got-used-to-rain",type:"choice",prompt:"Moving to London was hard, but I soon ___ the rain.",options:["used to","got used to","get used to","am used to"],answer:1,rule:"Became accustomed in the past → got used to + noun",explain:"Soon shows a change in the past: you became accustomed, so use got used to + noun. 'I used to the rain' has no main verb.",ruHint:"«Скоро привык» — процесс в прошлом: got used to."},{id:"ut-did-you-use-to-live",type:"reorder",words:["did","you","use","to","live","near","the","sea"],end:"?",rule:"Question: Did + subject + use to + V1?",explain:"Questions with used to work like other past simple questions: Did + you + use to + V1.",ruHint:"«Раньше жили у моря?» — Did you use to live…?"}]},{id:"sequence-of-tenses",group:"key",name:"Sequence of Tenses",ruName:"Согласование времён",short:"After said, thought or knew, the tense moves one step back",idea:"В русском время после «сказал, что…» остаётся как в живой речи: «Она сказала, что она дома». В английском, если главный глагол в прошедшем (said, told, thought, knew), всё после него обычно отступает на шаг в прошлое: She said she was at home. Этот was — не новое прошлое, а эхо от said: is → was, will → would, has done и did → had done.",category:"passive-reported",forms:[{label:"is → was",parts:["am / is / are","→","was / were"],example:"“I'm at home.” → She said she **was** at home."},{label:"do → did",parts:["present simple","→","past simple"],example:"“I work from home.” → He said he **worked** from home."},{label:"will → would",parts:["will + V1","→","would + V1"],example:"“I'll call you.” → He said he **would call** me."},{label:"has → had",parts:["have / has + V3","→","had + V3"],example:"“I've finished.” → She said she **had finished**."},{label:"did → had done",parts:["past simple","→","had + V3"],example:"“We missed the bus.” → They said they **had missed** the bus."},{label:"can → could",parts:["can / may","→","could / might"],example:"“I can help.” → He said he **could help**."}],timeline:{marks:[{kind:"point",at:-.8,label:"…had left (before)"},{kind:"point",at:-.45,label:"She said… was busy"},{kind:"point",at:-.1,label:"…would call (after)"}],caption:"Everything is measured from 'said', not from now."},uses:[{en:"Reporting what someone said",ru:"После said, told, explained время отступает на шаг: is → was, is doing → was doing, does → did, will → would, has done → had done. Past simple можно и не менять, если и так ясно, что это было раньше; had done, would, could, should, might не меняются.",example:{en:"She said she **was** busy.",ru:"Она сказала, что занята."}},{en:"Thoughts, hopes, knowledge",ru:"То же правило после thought, knew, hoped, was sure. Русское «думали, ты дома» по-английски звучит со сдвигом: We thought you were at home.",example:{en:"We didn't know you **were** Anna's brother.",ru:"Мы не знали, что ты брат Анны."}},{en:"would = will in the past",ru:"Будущее, увиденное из прошлого, передаётся через would + V1: «обещал, что позвонит» = promised he would call.",example:{en:"He promised he **would send** the contract on Friday.",ru:"Он обещал, что пришлёт договор в пятницу."}},{en:"Reported questions",ru:"Косвенный вопрос — уже не вопрос: порядок слов прямой (подлежащее, потом глагол), без do, does, did. Вопрос «да или нет» вводится через if или whether.",example:{en:"He asked me why I **was learning** English.",ru:"Он спросил, зачем я учу английский."}},{en:"Still true: shift optional",ru:"Если сказанное верно и сейчас (факт, всё ещё актуально), сдвиг можно не делать: оба варианта правильные. А если главный глагол в настоящем (says, thinks), сдвига нет вовсе.",example:{en:"He said the Earth **is** round.",ru:"Он сказал, что Земля круглая."}}],signals:[{word:"said (that)",note:"that можно опустить: She said (that) she was tired"},{word:"told me / told Anna",note:"в пересказе после told нужно «кому»; said me — ошибка"},{word:"asked if / whether",note:"косвенный вопрос «да или нет»"},{word:"asked where / why / how",note:"дальше прямой порядок слов: where I lived"},{word:"thought / knew / hoped",note:"то же правило, что после said"},{word:"promised / was sure",note:"будущее после них — would"},{word:"wanted to know / wondered",note:"тоже вводят косвенный вопрос"},{word:"says / thinks (present)",note:"главный глагол в настоящем — сдвига нет"}],versus:[{tense:"future-simple",ru:"Said — разговор был в прошлом, поэтому will обычно превращается в would. Says — он говорит это сейчас, will остаётся.",a:{en:"Max said the parcel **would arrive** on Monday.",ru:"Макс сказал, что посылка придёт в понедельник."},b:{en:"Max says the parcel **will arrive** on Monday.",ru:"Макс говорит, что посылка придёт в понедельник."}},{tense:"present-simple",ru:"Said сдвигает is в was, хотя по-русски в обоих случаях «довольна». После says сдвига нет.",a:{en:"Anna said she **was** happy in her new job.",ru:"Анна сказала, что довольна новой работой."},b:{en:"Anna says she **is** happy in her new job.",ru:"Анна говорит, что довольна новой работой."}}],mistakes:[{wrong:"He said he will call me, but he never did.",right:"He said he would call me, but he never did.",why:"Обещанный звонок уже в прошлом (he never did), то есть это будущее, увиденное из прошлого: после said нужен would."},{wrong:"We thought you are at home.",right:"We thought you were at home.",why:"После thought время сдвигается: are → were, хотя по-русски «думали, ты дома»."},{wrong:"She asked me where do I work.",right:"She asked me where I worked.",why:"В косвенном вопросе нет do / did и порядок прямой: where I worked (или where I work, если это всё ещё так); так же where she was, а не where was she."},{wrong:"He asked me do I like sushi.",right:"He asked me if I liked sushi.",why:"Вопрос «да или нет» в косвенной речи вводят через if или whether, без do."},{wrong:"She said me that she was tired.",right:"She told me that she was tired.",why:"После said не ставят «кому» без to: told me или said to me."},{wrong:"When I arrived, Ivan said the meeting has already started.",right:"When I arrived, Ivan said the meeting had already started.",why:"Это рассказ о прошлом: встреча началась раньше, чем Иван это сказал, поэтому has started → had started."}],trick:"Глагол в прошедшем (said, thought, knew) отправляет всё, что после него, на ступеньку назад: is → was, will → would, has done / did → had done. Русский так не делает, поэтому «думали, ты дома» переводи со сдвигом: We thought you were at home. Если сказанное верно и сейчас, сдвиг можно не делать, но со сдвигом почти никогда не ошибёшься.",examples:[{en:"The receptionist said our room **wasn't** ready yet.",ru:"Администратор сказал, что наш номер ещё не готов."},{en:"They told us the new office **would open** in spring.",ru:"Нам сказали, что новый офис откроется весной."},{en:"We thought you **were** still in Berlin!",ru:"Мы думали, ты ещё в Берлине!"},{en:"We knew she **had left** the company, but nobody knew why.",ru:"Мы знали, что она ушла из компании, но никто не знал почему."},{en:"The manager asked if we **had finished** the tests.",ru:"Менеджер спросил, закончили ли мы тесты."},{en:"My friend asked me where I **was going** on holiday.",ru:"Друг спросил, куда я еду в отпуск."},{en:"Did she say when she **would be** back?",ru:"Она сказала, когда вернётся?"},{en:"He didn't tell us that the flight **was delayed**.",ru:"Он не сказал нам, что рейс задерживается."},{en:"We hoped you **could** join us for dinner.",ru:"Мы надеялись, что ты сможешь с нами поужинать."},{en:"Tom says he **will be** late, so let's start without him.",ru:"Том говорит, что опоздает, так что давайте начнём без него."}],exercises:[{id:"sot-said-was-tired",type:"choice",prompt:"Last night Kate said she ___ tired, so we stayed in.",options:["is","was","will be","has been"],answer:1,rule:"Past reporting verb → is becomes was",explain:"Said is past, so the tense after it moves one step back: is → was.",ruHint:"После said: «сказала, что устала» → she was tired."},{id:"sot-thought-on-holiday",type:"errorTap",sentence:"We thought you are on holiday, so we didn't call.",wrong:3,correct:"We thought you were on holiday, so we didn't call.",rule:"After thought, are → were",explain:"Thought is past, so the verb after it moves back: you were on holiday.",ruHint:"После thought — were, а не are."},{id:"sot-thought-were-at-work",type:"fill",before:"Oh, you're here! I thought you ",after:" at work today.",answers:["were","would be","were going to be"],base:"be",rule:"I thought + past: are → were",explain:"Thought is past, so are moves back to were. English needs were (or would be, about later today) here, even though Russian keeps the present.",ruHint:"После thought: are → were (по-русски «думали, ты на работе»)."},{id:"sot-said-would-meet",type:"fill",before:"Nina said she ",after:" us at the station, but she didn't come.",answers:["would meet","was going to meet","was meeting","would be meeting","could meet"],base:"meet",rule:"will → would after said",explain:"Nina said 'I will meet you'. After said, will becomes would: she would meet us. Was going to meet, was meeting and could meet (from can) also work.",ruHint:"«Сказала, что встретит» — would meet."},{id:"sot-asked-where-i-lived",type:"choice",prompt:"He asked me where ___.",options:["did I live","do I live","I lived","lived I"],answer:2,rule:"Reported question → statement word order",explain:"A reported question is not a real question: subject + verb, no did. He asked me where I lived.",ruHint:"Косвенный вопрос: прямой порядок слов, без did."},{id:"sot-asked-if-seen-keys",type:"reorder",words:["he","asked","us","if","we","had","seen","his","keys"],rule:"Yes/no reported question → if + statement order",explain:"Use if for a yes/no question, then normal word order. 'Have you seen…?' moves back to had seen.",ruHint:"«Спросил, не видели ли мы его ключи» — if + прямой порядок."},{id:"sot-bus-had-left",type:"choice",prompt:"When we got to the stop, a man said the bus ___ ten minutes earlier.",options:["has left","leaves","had left","will leave"],answer:2,rule:"Earlier than the past report → had + V3",explain:"The bus left before the man spoke, and both are in the past, so use had left.",ruHint:"Раньше момента «сказал» — had + V3."},{id:"sot-says-will-send",type:"choice",prompt:"Mila says she ___ the report tomorrow, so don't worry.",options:["will send","would send","had sent","sent"],answer:0,rule:"Present reporting verb (says) → no backshift",explain:"Says is present, so nothing moves back: will send stays will send.",ruHint:"Says — настоящее, поэтому will остаётся."}]}].map(e=>{let o=n.g.safeParse(e);if(!o.success)throw Error(`Invalid tense entry ${e.id}:
${t.z.prettifyError(o.error)}`);return o.data}).sort((e,t)=>o.indexOf(e.id)-o.indexOf(t.id));e.s(["h",0,a,"P",0,[{aspect:"Simple",cells:["past-simple","present-simple","future-simple"],forms:["I worked","I work","I'll work"]},{aspect:"Continuous",cells:["past-continuous","present-continuous","future-continuous"],forms:["I was working","I'm working","I'll be working"]},{aspect:"Perfect",cells:["past-perfect","present-perfect","future-perfect"],forms:["I had worked","I've worked","I'll have worked"]},{aspect:"Perfect continuous",cells:["past-perfect-continuous","present-perfect-continuous","future-perfect-continuous"],forms:["I had been working","I've been working","I'll have been working"]}],"t",0,function(e){return a.find(t=>t.id===e)??null},"Q",0,function(e){return a.filter(t=>t.group===e)}],64405);var i=e.i(73812);function r(e,t){return`tense-${e}-${t}`}e.s(["x",0,0,"B",0,function(e,t){return{...t,id:r(e.id,t.id)}},"r",0,function(e,t){let n=(0,i.E)(e,0).answers;return{right:t.exercises.filter(e=>n[r(t.id,e.id)]?.correct).length,total:t.exercises.length}}],2512)}]);